window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_099"]={"n":"贝琼","dyn":"明","poems":[{"t":"西湖竹枝","f":"七言绝句","c":["六月玉泉来看鱼，湖头雨过尽芙蕖。","芙蕖花开郎更远，玉泉鱼少亦无书。"]},{"t":"董逃行","f":"七言古诗","c":["北风破肉胡兵利，汉将驱人死胡地。","丈夫四出妇女号，长安十日城门闭。","夜入南山忍冲虎，尚胜迢迢随捕虏。","城中有地尽蓬蒿，城下何人种禾黍。","夜闻《董逃》四面歌，却思乡土泪滂沱。"]},{"t":"杂诗七首 其六","f":"五言古诗","c":["春山一雨过，百草皆纵横。","百草不出山，山中人远行。","怀金别妻子，殉禄辞父兄。","寒暑忽已易，燕赵千里程。","龙门能碎舟，风浪安可争。","性命轻鸿毛，苦为朝暮营。","愧此山中草，萋萋林下生。"]},{"t":"杂诗七首 其七","f":"五言古诗","c":["薛公未罢相，宾客竞相倾。","一朝偶失意，门无珠履声。","贵贱已如此，何论死与生。","秋燕辞空室，春蝶抱留英。","盈虚信物理，聚散亦人情。","达士甘寂寞，力耕谢华缨。","道尊岂恋禄，心远孰希名。","腐鼠非吾饵，朱凤以时鸣。","悠然动遐想，五鼎益为轻。"]},{"t":"真真曲","f":"五言古诗","c":["断丝弃道边，何日缘长松。","堕羽别炎洲，不复巢梧桐。","请君且勿饮，听我歌懊憹。","在昔全盛时，冠盖纷相从。","盘游易水上，意气天山雄。","金刀手割鲜，酒给葡萄浓。","坐有一枝春，秀色不可双。","娉婷刘碧玉，绰约商玲珑。","宝髻金雀钗，已觉燕赵空。","或闻操南音，未解歌北风。","上客惊且疑，姓字初未通。","问之惭复泣，乃起陈始终。","妾本建宁女，远出西山翁。","父母生妾时，谓是金母童。","梨花锁院落，燕子窥帘栊。","迢迢官朔方，南归山水重。","侵贷国有刑，桎梏加父躬。","鬻女以自赎，白璧沦泥中。","秋娘教歌舞，声价倾新丰。","永为倡家妇，遂属梨园工。","览镜拂新翠，吹箫和小红。","身居十二楼，屡入明光宫。","京华多少年，门外嘶青骢。","自伤妾薄命，失路随秋蓬。","不如孟光丑，犹得嫁梁鸿。","客闻为三叹，祖德宁未崇。","回黄忽变绿，人事何匆匆。","有客伤缇萦，无人怜蔡邕。","遣使白丞相，削籍归旧宗。","小史三十馀，勿恨相如穷。","配汝执箕帚，今夕看乘龙。","鸳鸯并玉树，鹦鹉开金笼。","银甲不复整，红牙不复摐。","提瓮自汲水，絺绤亦御冬。","应非事羊侃，颇类归建封。","琵琶感商妇，老大犹西东。","崔徽怨憔悴，浪写丹青容。","依依章台柳，落絮春无踪。","小妾恨题驿，竟与琼奴同。","时多困坎坷，事或欣遭逢。","焉知百尺井，歘登群玉峰。","借问为者谁，内相姚文公。"]},{"t":"十月既望凤皇山晚归","f":"五言古诗","c":["村黑畏冲虎，且复归柴门。","风林月未出，宿鸟争且喧。","浮云忽断续，万丈飞金盆。","湛湛天宇高，光气相吐吞。","我行月还逐，是身亦无根。","试求不死药，飞腾同久存。","老妻有斗酒，洗盏当前轩。","酌酒消我忧，万事俱忘言。"]},{"t":"赠迮元霖","f":"五言古诗","c":["迮生固长贫，赋诗朝忍饥。","破裘连百结，但觉诗愈奇。","锵然击天球，未作秋蛩悲。","呜呼识者死，举国无人知。","鼓柁洞庭湖，远过三高祠。","我无一斗酒，为生开两眉。","宇宙非不大，四顾将安之。","日落万山黑，百鸟争寒枝。","翩翩五色凤，寂莫双翅垂。","圣人坐明光，迟汝一来仪。"]},{"t":"耕乐轩","f":"五言古诗","c":["隐者东海头，安时事耕凿。","有田百亩馀，相率治境埆。","我稼没牛腹，我书挂牛角。","三洲雷雨均，既耕必有穫。","吹箫赛田租，操豚不为薄。","上给县官租，酣歌见真乐。","江南风景异，况乃赋敛数。","连云桑柘尽，池台总零落。","尚恐兵未休，远近无土著。","全生虎豹群，岂忍厌藜藿。"]},{"t":"郊居","f":"五言律诗","c":["直木恶为轮，疲马思卷旆。","匡时既非才，处约斯寡悔。","采《诗》鉴兴亡，读《易》明进退。","永怀嵇阮放，甘与沮溺对。"]},{"t":"送潘时雍归钱唐","f":"五言古诗","c":["海县兵未息，公子今何之。","酌君葡萄酒，听我白苧词。","忆昔来黄湾，始为童子师。","诸生老伏胜，说客惭张仪。","连床风雨夕，秉烛听新诗。","殷殷金石声，真足解我颐。","同居石壁下，斗柄倏三移。","脱略势利交，所贵两不疑。","久怀地主恩，亦有莼鲈思。","束书向钱唐，磬折从此辞。","钱唐寔都会，西湖天下奇。","朱楼起相对，上有千蛾眉。","羽衣何翩翩，处子冰雪肌。","楼前五陵儿，并马金鞭垂。","酒酣复张乐，但惜白日驰。","近者属凋丧，不及全盛时。","空山凤皇去，月黑号狐狸。","春风吹行殿，碧草生荒基。","何当从子游，观涛酹鸱夷。","辛苦草《太玄》，徒为廉蔺嗤。","子实济时具，飞腾方在兹。","匠石既已遇，小大随所施。","从容宰相前，奋舌论安危。","岂无一尺箠，盗贼不足笞。","天空羽毛急，水涸舟楫迟。","临岐更挥泪，中年伤别离。"]},{"t":"荅客","f":"五言古诗","c":["窃禄非本性，适彼南山阿。","藜藿日不充，慷慨独商歌。","有客向我言，与世同其波。","商君震七国，季子倾三河。","区区守章句，白首成蹉跎。","念之为三叹，所乐良已多。","潜鱼骇钩饵，飞鸟愁网罗。","结驷非不荣，违己当如何。"]},{"t":"春日宴沧洲诗","f":"五言古诗","c":["天阔无留云，山明洗新黛。","过从属休假，置酒沧洲会。","柔荑绿堪藉，杂英红尚在。","累觞既不辞，秉烛还相对。","清弹促哀响，秘舞呈脩态。","兰亭今已矣，金谷徒增慨。","大化会有终，四时宁复贷。","厌厌夜无归，从人讥倒载。"]},{"t":"采芝生诗三首 其三","f":"五言古诗","c":["负版行欲僵，飞蝇死犹集。","赴烛夜蛾焚，好酒猩猩泣。","所以思远托，道路方险涩。","宁希百金赏，岂慕千户邑。","永言从我求，鹪鹩惟一粒。","有材寔为累，无欲安所入。","韩彭苦不悟，羞同匹夫执。","商山今寂寥，高风邈难及。"]},{"t":"读史五首 其一","f":"五言律诗","c":["吾怜闵仲叔，始辟怀喜惧。","及其见司徒，喜惧亦皆去。","劳苦非所堪，虚名岂相误。","用舍何必言，投劾时已暮。"]},{"t":"读史五首 其二","f":"五言律诗","c":["周燮久不仕，身屈名四驰。","玄纁一旦至，举族更劝之。","安知修道者，出处亦有时。","慨然中途返，独守东冈陂。"]},{"t":"读史五首 其三","f":"五言律诗","c":["东汉多逸民，山栖久怀璧。","法真亦逃名，讵屑三公职。","求蝉在明火，求士当务德。","此道今何如，其人安可识。"]},{"t":"读史五首 其四","f":"五言律诗","c":["樊英抗高节，万乘不能屈。","设坛为见之，岂若壶山逸。","光禄位已崇，匡时竟无术。","遂兴张楷讥，尚待黄琼出。"]},{"t":"读史五首 其五","f":"五言律诗","c":["五侯浊四海，白日沦光辉。","处士切忧国，空言相是非。","郭泰不绝俗，申屠能见机。","朱凤翔千仞，百世令人希。"]},{"t":"巳酉岁初度日书怀","f":"五言古诗","c":["余生若小草，望成百尺材。","强因客土植，苦被秋风摧。","徒惭五十过，况经元二灾。","白发不可变，青阳忽已回。","未忘药裹好，几见桃花开。","残编掩黄石，虚室生苍苔。","故人且共弃，王孙谁复哀。","终归葛洪井，讵上凤皇台。","衰荣置勿论，待月酌金罍。"]},{"t":"初夏郊居二首 其一","f":"五言古诗","c":["强学不知老，索居恒鲜欢。","誓将从余好，山河阻且绵。","凄凄风雨交，四月秋浦寒。","夕寝不能旦，日高犹未餐。","念之安所尤，通塞固有偏。","庶无外患及，力稼或逢年。"]},{"t":"初夏郊居二首 其二","f":"五言古诗","c":["仲夏桑扈鸣，气清天愈高。","新田己当治，南风翼良苗。","田翁起相戒，庶务东作劳。","丰年谅可必，勿为蔓草交。","嗟余失路久，竟负伊人招。","屡空亦宜然，何日耕东皋。"]},{"t":"对酒怀邵文博拟东野","f":"五言古诗","c":["今日忽不乐，绿酒徒盈樽。","酌酒云解愁，愁生如有根。","安得二三子，促席相与言。","尚思沧洲地，十月花更繁。","云随鹤盖合，雪避貂裘温。","终筵复秉烛，歌吹高堂喧。","盈盈二八女，白苧鹤翎翻。","月落犹未归，清夜宿西园。","到今题诗处，素壁龙蛇昏。","荆扬忽云扰，海内俱星奔。","断肠临濠谪，回首颍上屯。","昔如鹰脱韝，竟作驹在辕。","凄凉城南路，甲第今空存。","潇湘窗下流，三神锁朱门。","江险隔秋梦，山寒啼夜魂。","讵忘白璧赠，更恋绨袍恩。","索居怅无匹，落叶满孤村。"]},{"t":"早春","f":"五言律诗","c":["山寒花尚迟，雪霁江已绿。","怀新感游子，哢节喧众族。","且同尊俎乐，幸免章绶束。","更拟登前峰，青郊可游目。"]},{"t":"题盛苍崖雁","f":"五言古诗","c":["八月鸿雁来，往彼天南陬。","前飞倦已息，后至饥相求。","日落洞庭晚，风高彭蠡秋。","彭蠡多蒹葭，远近弥汀洲。","恒恐羽毛损，稻粱非所谋。","寒门阻冰雪，异乡安可留。","徘徊念其族，天外复千俦。","身今万里客，肉非九鼎羞。","慎为弋者获，远寄征人愁。","愿以海为池，上同朱凤游。","饮啄全微躯，不愧波上鸥。"]},{"t":"初冬","f":"五言古诗","c":["一气变昏旦，洞房风露凄。","田禽亦已化，秋兰同蒺藜。","为客久成老，怀人殊未夷。","惨惨白日暮，迢迢归路迷。","世衰不获骋，天远何由稽。","永思读书台，言采山中荑。"]},{"t":"拟东野","f":"五言古诗","c":["破屋夜通月，霜气刀棱棱。","病骨不受寒，卒岁仍无缯。","残灯吐复翳，僵卧如冻蝇。","事业惭蒸沙，文章空镂冰。","已失国士意，颇为年少陵。","长歌独慷慨，坐候东方升。"]},{"t":"秋怀 其一","f":"五言古诗","c":["露下百草变，凄凄天地秋。","亦如中年客，玉颜安可留。","山鸣迅商激，水涸行潦收。","恩方改团扇，意复存弊裘。","梧桐叶尽脱，孤雏夜啾啾。","光景忽已逝，感之双涕流。"]},{"t":"拟古","f":"五言古诗","c":["荆山一何高，上与天门通。","犹闻产玉处，吐气成白虹。","县藜混燕石，世已无国工。","琢之惧不完，不如在石中。","卞和耻再刖，玉亦悲无穷。","吾今死抱璞，庶以全其躬。"]},{"t":"晚眺","f":"五言古诗","c":["极目登高丘，秋高淮泗平。","淮泗东南流，故绕钟离城。","东京昔丧乱，英雄纷战争。","杀人及鸡犬，旷野寂无声。","悠悠千载下，复见新人耕。","魏公今何在，铜台春草生。","公路冢中骨，岂忧王室倾。","北海固为豪，平原安可轻。","时哉有屈信，汉道再昌明。"]},{"t":"四月十日儿子翱■来凤阳留一月遣归因令早营草堂殳山下为止息之所云","f":"五言古诗","c":["老病不得归，独处常戚戚。","二子江南来，眼暗初未识。","生常戒垂堂，肌肉如雪白。","一月长途间，海风吹尽黑。","买酒为相劳，问荅向中夕。","迢迢汉阳簿，春来断消息。","阿宣在母傍，颇知工翰墨。","艰难且拨弃，倏使沈忧释。","所愧无定居，百岁半为客。","经营须及早，尚爱龙湫僻。","况近读书台，云销四山碧。","泉深出丹砂，地冷多琥珀。","既非匡世资，庶遂陶阮逸。","良辰戒僮仆，匆匆又南北。","五月方郁蒸，日气成霞赤。","出入非所宜，川陆慎所历。","惜别岂无泪，向汝难再滴。","秋江有鲈鱼，当挂吴淞席。"]},{"t":"游菩提山值雨宿存思庵","f":"七言古诗","c":["连山插天危欲崩，木客结构当千层。","我来看山风雨恶，入山喜见灵泉僧。","闭门留客共野饭，风回雨绝清无蝇。","酒酣熟寝唤不起，夜深花落龛中灯。","轩辕已恐即韩愈，许汜未可讥陈登。","天明童仆催欲去，却叹世故来相仍。","重寻曲折恐蹉跌，安得远讨闲支藤。","林开川豁见鸟下，山寒石峻愁猿腾。","呼舟独返草堂路，他日重来共毾㲪。"]},{"t":"凤皇山歌","f":"七言古诗","c":["大城周回三百雉，紫微阁对吴山起。","天目西来为凤皇，苍然不过钱唐水。","玉辇金舆北去赊，行人折尽上阳花。","杜鹃夜叫葛洪井，燕子春归苏小家。","燕归不识更新主，王气凄凉作风雨。","城南杨柳郁金黄，一束纤腰为谁舞。"]},{"t":"送浙省都事曹德辅运粮北上","f":"七言古诗","c":["屯田未开岁未熟，白粲一金才一斛。","将军初下山东城，使者复转江南粟。","飓风五月西南回，黄龙朱雀一时开。","雷霆夜槌海若死，云雾昼合天妃来。","黑洋北去五千里，直沽近接金河水。","内廷传敕赐宫壶，侍臣出报龙颜喜。"]},{"t":"天冠法师邓均谷祷雨歌","f":"七言古诗","c":["至正辛丑秋七月，官河无舟死鱼鳖。","钱唐城中十万室，凿井深通海鳅穴。","海底九乌朝并出，流金铄石气愈烈。","我无快刃斫旱魃，构孽为妖降吴越。","老巫歌舞帝不悦，真宰之罪何当雪。","天冠法师与天通，丹书铁券呼龙公。","石坛昼晦群神降，金支翠旗来半空。","举杯掷地霹雳从，澍雨一日声如硔。","三田白水禾芃芃，儿童满道歌年丰。","百金不顾归空同，师岂琐琐贪天功，笑汝蜥蜴能为龙。"]},{"t":"次韵铁厓先生醉歌","f":"七言古诗","c":["先生爱酒称酒仙，清者为圣浊为贤。","清江三月百花合，江头日坐流萍船。","左携张好右李娟，紫檀双凤鹍鸡弦。","倾家买酒且为乐，老妇勿忧无酒钱。","白日西没天东旋，秋霜入镜何当玄。","蓬莱有路不可到，祖龙已腐三重泉。","何如快饮三万日，酒楼即起糟丘边。","愿持北斗挹东海，月落枕股楼头眠。"]},{"t":"行路难","f":"古风","c":["采玉于阗河，问君勃律何。","时过采珠鲛人室，问君百粤何时出。","珠玉岁久同为尘，君胡重利不重身。","海有波，缺我楫，山有石，摧我轮。","行路难，出门即羊肠，何况万里道。","管叔危周公，匡人仇鲁叟。","尊有酒，盘有壶，鼓坎坎，歌乌乌。","海不可涉，山不可徒。","路旁之人，爱尔玉与珠。","行路难，我以为父，安知非虎。","我以为兄，安知非狼。","仰天悲歌，泣下沾裳。"]},{"t":"雨中","f":"七言古诗","c":["江南正月如腊月，花开未开春尚悭。","空中白雨急飞瀑，海上黑云深抱山。","老夫闭门愁不出，十日西窗听萧瑟。","公卿鞴马五更朝，且独高眠舒我膝。","铜雀破瓦不补天，哦诗强学号风蝉。","荒村无路竹鸡唤，载酒何人寻郑虔。","白头为农计亦足，弃书耕田买黄犊。"]},{"t":"正月廿九日杨鸣鹤席上分韵得几字","f":"七言古诗","c":["两山昨夜风雨止，水涨新痕没沙尾。","黄知彭泽柳初芽，红见武陵桃欲蕊。","老去逢春更惜春，平生酒伴谁知己。","白发杨郎古奇士，千金已散归田里。","闭门留客为张筵，共喜一时成二美。","小儿行觞不计筹，大儿割肉能操匕。","冬殖下箸白于肪，秋藕洗泥寒刺齿。","且须快意在今朝，况我中年会能几。","乱离相见亦偶然，海内交游半为鬼。","颠狂岂顾傍人毁，但恨白日无淹晷。","赋诗已觉无曹刘，骂客安知有程李。","坐中一鹤能商歌，歌作连珠尽倾耳。","风卷新声入夜云，豪竹哀丝静如水。","若为倒卷玻瓈江，百尺高楼眠不起。"]},{"t":"丁一鹤以疾止酒诗以诮之","f":"古风","c":["一鹤先生老耽酒，夜饮一石朝五斗。","春来连月醉如泥，窥户欣无太常妇。","杜康昨者忽为厉，鹦鹉不荐谈天口。","结交昔在王侯间，折节应羞儿女后。","地经槜李却垂泪，日落君山独回首。","浪说北游年少时，结束正似幽并儿。","朔风破肉雪埋胫，桃花骏马如星驰。","天街下马意气盛，胡女起问郎君谁。","凉州葡萄不论价，龟兹觱栗当筵吹。","安知反覆一秋梦，白发渐满红颜衰。","吴王宫中走麋鹿，真娘墓下号狐狸。","出门两足苦无力，强与老儒时赋诗。","君不见人间万事随流水，别有乾坤醉乡里。","不如与君更挟两鸱夷，李白陶潜共生死。"]},{"t":"穆陵行","f":"七言古诗","c":["六陵草没迷东西，冬青花落陵上泥。","黑龙断首作饮器，风雨空山魂夜啼。","当时直恐金棺腐，凿石通泉下深固。","一声白雁度江来，宝气竟逐妖僧去。","金屋犹思宫女侍，玉衣无复祠官护。","可怜持比月氏王，宁饲乌鸢及狐兔。","真人歘见起江东，铁马九月踰崆峒。","百年枯骨却南返，雨花台下开幽宫。","流萤夜飞石虎殿，江头白塔今不见。","人间万事安可知，杜宇声中泪如霰。"]},{"t":"巳酉清明","f":"七言古诗","c":["白纻衣鲜紫骝马，清明酌酒梨花下。","马蹄一去不复来，梨花又见清明开。","城南城北多新墓，日落啼鸦满高树。","有酒谁浇千岁魂，子孙尽发濠州住。","主人更劝金叵罗，阿蛮起舞玲珑歌，生前不饮君如何。"]},{"t":"余避地千金圩屡游殳史两山酒酣兴发赋诗一首惜山中无赏昔者空乘亦同于瓦器耳姑录以自娱云","f":"七言古诗","c":["神人夜割蓬莱股，苍然尚作青狮舞。","殳基得道此飞腾，烟火千家自成坞。","前年盗起官军下，存者如星才四五。","我来欲置读书床，出入未愁穿猛虎。","山寒月黑无人声，夹道长松作风雨。","佩环何日归公主，泉下铜棺閟千古。","石仆麒麟罢官守，林宿鸱鸮闻鬼语。","苦耽胜概惜残年，共说当时悲老父。","锦绣池台已零落，田翁八十锄新土。","伤哉土俗尊巫觋，伏腊荒祠沸箫鼓。","祠旁凿井深不枯，云气随龙有时吐。","试上崔嵬望沃洲，直将培鞬齐天姥。","春前野桃浑欲放，雪尽黄精亦堪煮。","兴来起挟李长庚，重载琵琶双玉女。"]},{"t":"郭忠恕出峡图","f":"楚辞体","c":["巫峡何危哉，夹拱如龙门。","禹治九州不得到此，峡口水作雷霆奔。","问汝江中人，几日三巴去。","峨嵋五月销古雪，滟滪堆深虎须怒。","巫峡之险安可攀，胡为吴樯楚柁日日来往乎其间。","高堂中有如花颜，银屏翠箔青春闲。","涉此万里道，经年犹未还。","黄金不买死，直欲高南山。","汝舟非龙汝非虎，鼋鼍出没馋蛟舞。","前者已脱后者号，江神无情天又雨。","石巉岩兮利刃攒，一叶宛转行千盘。","睹此魂魄悸，岂待杜宇夜叫猿声酸。","安得凿之尽平土，万古不识风波苦。"]},{"t":"送迮士霖归天台","f":"七言古诗","c":["赤城云气神仙家，千树万树蟠桃花。","十二楼台起花外，石门水长通胡麻。","当时刘郎亦草草，出山却忆山中好。","莫信丹丘日月长，玉人已共桃花老。","山空水流云自飞，刘郎看花须早归。"]},{"t":"张继善寄桃源图日赋诗","f":"七言古诗","c":["张生寄我《桃源图》，桃源有路归何日。","高堂坐见武陵溪，犬吠鸡鸣犹髣髴。","云气挟山山欲行，山穷水阔桃花明。","仙家只在流水外，世上无人知姓名。","一日花间问渔者，山河百二如崩瓦。","赤帝西来祖龙死，复见同槽有三马。","太康去秦六百秋，子孙生长不知忧。","商颜黄绮亦何事，白发出侍东宫游。","龙争虎战俱寂寞，绝境空存已非昨。","种桃何必指秦人，春到花开又花落。"]},{"t":"题董源寒林重江园","f":"古风","c":["天下画师无董源，学者纷纷工水石。","云山万里出巴陵，白首淮南见真迹。","乱石平坡净无土，松根裂石蟠龙虎。","偃盖千年饱雪霜，深林六月藏风雨。","江上村墟何处入，浮空远黛蛾眉湿。","渔人日暮各已归，小舟如凫落潮急。","我昔西清尝看画，南唐此本千金价。","坐移绝境在云间，月出霜猿啼后夜。","薄游未挂吴淞帆，令我一夕思江南。","安得买田筑室幽绝境，开窗日日分晴岚。"]},{"t":"送王克让员外赴陕西","f":"七言律诗","c":["貂裘万里独冲寒，旧是含香汉署官。","白雪作花人面落，青山如凤马头看。","关中相国资王猛，海内苍生望谢安。","应念东南有遗佚，采芝深谷尚盘桓。"]},{"t":"十月闻雷","f":"七言律诗","c":["天气初寒春尚赊，坎中夜半有鸣蛙。","百年宇宙喧戎马，十月雷霆起蛰蛇。","老柳黄垂霜后树，小桃红破雨中花。","三公燮理非无术，愁听空江度鬼车。"]},{"t":"清明日陪杨铁崖饮城东门是日风雨","f":"七言律诗","c":["荡舟挝鼓出东门，怪雨盲风野色昏。","海上一春犹作客，楼头三日共开樽。","青山石马新人冢，锦树黄鹂旧相园。","快意百年须痛饮，转头何处不销魂。"]},{"t":"即事","f":"七言律诗","c":["少海旌旗落照中，沙陀兵马雁门雄。","朝宗久废诸侯礼，翊戴方尊节度功。","今日岂宜求骑劫，当年应失倚全忠。","丹书铁券存终始，万古山河带砺同。"]},{"t":"经故内","f":"七言律诗","c":["山中玉殿尽苍苔，天子蒙尘岂复回。","地脉不从沧海断，潮声犹上浙江来。","百年禁树知谁惜，三月宫花尚自开。","此日登临解题赋，白头庾信不胜哀。"]},{"t":"雨中书怀","f":"七言律诗","c":["汉苑秦宫迹已陈，金沙一簇为谁新。","山河有恨空怀古，风雨无情只送春。","南国鹧鸪愁北客，东家胡蝶过西邻。","尊前莫唱升平曲，白发秋娘也自颦。"]},{"t":"秋思 其一","f":"七言律诗","c":["两河兵合尽红巾，岂有桃源可避秦。","马上短衣多楚客，城中高髻半淮人。","荷翻太液非前日，花落蕃禧又暮春。","莫上高楼望西北，远山犹学捧心颦。"]},{"t":"秋思 其二","f":"七言律诗","c":["翠柳无枝拂御堤，风来阊阖更凄凄。","玉笼别主鸳鸯拆，金井啼秋络纬齐。","水上拾红韩氏女，窗间织素窦家妻。","伤心又送韶华去，直似黄河不向西。"]},{"t":"秋思 其三","f":"七言律诗","c":["怅望知音阻汉皋，海门秋水欲成涛。","鹧鸪未肯随胡雁，燕子长教辟伯劳。","锦绣莫酬青玉案，琵琶空续紫檀槽。","可堪独闭帘栊坐，花影铺阶月正高。"]},{"t":"庚戌九日是日闻蝉","f":"七言律诗","c":["今日出门风雨收，东山西山须可游。","那能束带从王事，且复开尊破客愁。","雁别紫台初辟雪，蝉鸣红树不知秋。","桃花细菊应相笑，岁月无情自白头。"]},{"t":"二月一日病中口号","f":"七言律诗","c":["新年尤苦病相侵，白发无持自满簪。","五柳先生莲社约，四明狂客镜湖心。","满城风雨花时过，曲水东西草色深。","明日两峰茅屋下，故人持酒一开襟。"]},{"t":"送杨九思赴广西都尉经历","f":"七言律诗","c":["邛笮康居路尽通，西南开镇两江雄。","汉家大将推杨仆，蛮府参军见郝隆。","象迹满山云气白，鸡声千户日车红。","明珠薏苡无人辩，行李归来莫厌穷。"]},{"t":"送朱质夫赴宁远知县","f":"七言律诗","c":["万里番禺自汉通，乘槎有客气如虹。","地分铜柱风烟外，山涌璚台雪浪中。","帝子旌旗何处问，黎人衣服与时同。","兴来好和苏公语，又度西南月半弓。"]},{"t":"和张思广九月韵时王景行有约阻雨不赴","f":"七言律诗","c":["秋藕无花寄断丝，拒霜犹学汉宫姿。","锦袍江令还家早，白发秋娘对客悲。","剩水残山留胜槩，酸风苦雨失幽期。","未惭寂寞陶彭泽，更把黄花尽一卮。"]},{"t":"巳卯清明日偕马新仲李守中刘志远游聚宝山过泐季潭长老三塔院饮于志远赋诗","f":"七言律诗","c":["城南看花花正开，清明微雨洒尘埃。","路从周处台前过，山转曹彬庙下来。","堕地游丝轻复起，近人娇燕去仍回。","高歌击节狂欢赏，共尽生春酒一杯。"]},{"t":"殳山隐居夏日","f":"七言律诗","c":["病客从教懒出村，两山一月雨昏昏。","野花作雪都辞树，溪水如云忽到门。","无复元戎喧鼓吹，试从田父牧鸡豚。","来青处士时相过，犹是平原旧子孙。"]},{"t":"冬夜 其一","f":"五言律诗","c":["月斜窗户白，不寝夜何长。","避乱多空室，偷生且异方。","安巢无燕雀，竞肉有豺狼。","脉脉如葵藿，倾心待太阳。"]},{"t":"冬夜 其二","f":"五言律诗","c":["岁月悲游子，风尘老腐儒。","兵交连北冀，客隐向东吴。","草白秦皇道，天清陆瑁湖。","昔时游乐处，抚事一长吁。"]},{"t":"冬夜 其三","f":"五言律诗","c":["水阔三江地，山空十月时。","寒花禁露变，独树爱风攲。","老大将何事，漂沦幸托兹。","不忘忧国意，展转复成诗。"]},{"t":"寓翠岩庵 其三","f":"五言律诗","c":["莲社僧相引，柴门客屡回。","日高人语静，风远佛香来。","碧爱琅玕绕，红看踯躅开。","便应从此老，城郭有尘埃。"]},{"t":"寓翠岩庵 其四","f":"五言律诗","c":["蟏蛸当户罥，科斗满池生。","可惜春光去，何时晚计成。","病多添越思，愁减发秦声。","此意无人会，芳尊且独倾。"]},{"t":"晚眺","f":"五言律诗","c":["极目三边静，伤心万室空。","断山明落日，飞藿卷回风。","汉节无归使，夷歌有野童。","烟尘几时息，归钓古城东。"]},{"t":"过王景修","f":"五言律诗","c":["不识沧洲路，还经白石矶。","林深烟似织，江黑雨初飞。","野店多先闭，渔舟独未归。","幽人宅已近，薄暮扣柴扉。"]},{"t":"甲辰元旦","f":"五言律诗","c":["五十今朝过，谈经滞海滨。","天阴不见日，地冷未知春。","染翰题新语，开襟待故人。","宫花遍朝士，那上小乌巾。"]},{"t":"寒食三首 其一","f":"五言律诗","c":["不知春已过，一月雨声中。","蒲短初侵水，花残更受风。","病疑耽酒过，穷觉向诗工。","失喜闻莺语，飞来草屋东。"]},{"t":"夜泊","f":"五言律诗","c":["四更风露静，攲枕独无眠。","野阔天斜倚，江清月倒悬。","谁家横塞笛，有客荡归船。","可惜云深处，凄凉不及前。"]},{"t":"暮春杂诗 其一","f":"五言律诗","c":["世乱疲奔走，空伤万事非。","塞鸿还北度，戎马未南归。","乐土居人散，丰年野客饥。","闭门风雨过，一径落红稀。"]},{"t":"暮春杂诗 其三","f":"五言律诗","c":["四海尚风飙，千门转寂寥。","传闻收土地，思见复征徭。","节士心肝在，将军髀肉消。","何时听野老，鼓腹颂唐尧。"]},{"t":"澄林客居二首寄戴良佐沈复东 其一","f":"五言律诗","c":["借屋暂移家，当门亦舣槎。","地蒸云触石，江涨雨崩沙。","卢橘初垂颗，冬青未落花。","老夫无一事，日日醉流霞。"]},{"t":"排闷","f":"五言律诗","c":["白首尚为客，飘飘天一涯。","耳鸣通夜雨，眼暗隔年花。","畏酒从今断，题诗浪自誇。","有村如栗里，准拟更移家。"]},{"t":"壬子冬至日过来青堂三首示勉中祖南二友 其一","f":"五言律诗","c":["浪迹依刘表，忘形见陆生。","山中酿酒熟，雪后具舟迎。","好学来诸子，论诗过二更。","穷愁一披写，杯尽更须倾。"]},{"t":"壬子冬至日过来青堂三首示勉中祖南二友 其二","f":"五言律诗","c":["衣冠且从俗，犹有晋风流。","我爱陶贞白，人称马少游。","蜂房寒未割，鸡栅暖宜修。","不必论三仕，何如号四休。"]},{"t":"壬子冬至日过来青堂三首示勉中祖南二友 其三","f":"五言律诗","c":["扰扰知何事，人间即梦间。","试从千佛转，能见几人閒。","水落元通月，云行不碍山。","长歌和樵者，日暮抱薪还。"]},{"t":"题马文壁画二首 其二","f":"五言律诗","c":["小桥危跨壑，破屋幸依山。","避地人相过，朝天客未还。","麝眠春草外，猿挂古松间。","寂寞南窗月，残书亦久閒。"]},{"t":"黄湾述怀二十二韵寄钱思复","f":"五言古诗","c":["海岱初云扰，荆蛮遂土崩。","王公甘久辱，奴仆尽同升。","远适将妻子，端居谢友朋。","草堂森苦竹，瓜圃蔓寒藤。","地尽山光断，天昏海气蒸。","夜深常畏虎，秋后更多蝇。","鹤发愁难理，乌皮懒自凭。","娉婷羞不荐，龌龊怯先登。","拔剑歌谁和，闻笳寝复兴。","过逢欣已绝，疾病恨相仍。","自拟秦民去，重烦鲁使徵。","吹毛多见谪，刺舌尚须惩。","耆老惟君在，文章对客矜。","才全怀白璧，道重比朱绳。","虎榜名非忝，鸡林价尽增。","极知童子陋，深愧大巫称。","最忆春停骑，高谈夜剪灯。","病驹终弃掷，生鹘必飞腾。","迹已从信屈，时多任爱憎。","赋诗閒莫废，好事老犹能。","汉月今频满，天河本自澄。","山阴有孤棹，雪下兴还乘。"]},{"t":"丁未除夕","f":"五言古诗","c":["东风来日本，北斗辟玄枵。","坐并华榱荫，班违紫禁朝。","清觞陶令节，明烛炳通宵。","曲付蛾眉唱，香添鹊尾烧。","俗传傩逐厉，事类博成枭。","旧疾应全减，新欢且共要。","压城云暗度，侵幔雨斜飘。","红拆丛梅萼，青缄弱柳条。","明朝还献岁，更颂玉盘椒。"]},{"t":"壬子夏端居二湖与二三子读苦书而热如焚一坐四迁杜少陵发狂大叫非过言也回思云间时往来吕邵仁族其地有林薮之美池台之胜可以避暑而游士寓公咸会于此相与穷日夜为乐及兵变之后所至成墟海内忘形半为异物感衰荣之无定悼生死之相违遂成三十四韵粗述其事云","f":"五言古诗","c":["地僻从吾放，山深少客过。","昏昏蒸酷暑，郁郁抱沉痾。","断酒愁为敌，抛书睡作魔。","云生空望雨，水涸不通河。","唱和闻蛙吹，遨游记鹤坡。","辋川移绝境，瀑布激悬波。","数子论新好，诸翁乐太和。","百篇齐屈贾，五字逼阴何。","共哂佯狂彻，焉知好辩轲。","冰壶清莫比，铁砚老犹磨。","公子时同载，将军夜不诃。","结交真有道，与物总无他。","每喜方舟坐，何烦信马驮。","秋风千户竹，宿露半池荷。","席赌藏钩令，亭邀窃药娥。","颇黎行冻蚁，玛瑙进寒鼍。","潦倒衣从湿，敧倾弁或俄。","胡雏能觱栗，汉女善颦婆。","对舞翻朱袖，群讴敛翠蛾。","纷纷方大噱，浩浩渐微酡。","壶中恒三马，诗成愧一螺。","如何弃俎豆，却复老干戈。","落雁长淮远，蜚鸿大野多。","死生俱异域，出处不同科。","泪泣荆人玉，肠回织女梭。","秪怜成肮脏，及此叹蹉跎。","室已如悬磬，门今信设罗。","凌霄萦小草，平地引危柯。","水鸟浮沈戏，林蝉断续歌。","分甘留白屋，身免束青緺。","晚牧幽湖上，春耕曲涧阿。","丹砂寻旧井，金刹过祇陀。","岂复同般乐，应知废切磋。","茫然感平昔，兴发强吟哦。"]},{"t":"苕溪陆文宝挟笔过云间持卷求余言而一时缙绅之户不啻百篇有论笔法自赵松雪用落墨而始废者有为笔卦者近世肤学小子率意妄作类如此可叹也已因赋五绝 其一","f":"七言绝句","c":["近代何人下笔精，吴兴松雪最知名。","欲过大令归前辈，竞学中郎耻后生。"]},{"t":"苕溪陆文宝挟笔过云间持卷求余言而一时缙绅之户不啻百篇有论笔法自赵松雪用落墨而始废者有为笔卦者近世肤学小子率意妄作类如此可叹也已因赋五绝 其二","f":"七言绝句","c":["吴兴松雪真奇士，书到通神逼二王。","谩有儿童誇并驾，更无弟子得升堂。"]},{"t":"苕溪陆文宝挟笔过云间持卷求余言而一时缙绅之户不啻百篇有论笔法自赵松雪用落墨而始废者有为笔卦者近世肤学小子率意妄作类如此可叹也已因赋五绝 其三","f":"七言绝句","c":["退之作传聊为戏，子云草《玄》真好奇。","更有区区工画卦，强分奇耦学庖牺。"]},{"t":"苕溪陆文宝挟笔过云间持卷求余言而一时缙绅之户不啻百篇有论笔法自赵松雪用落墨而始废者有为笔卦者近世肤学小子率意妄作类如此可叹也已因赋五绝 其四","f":"七言绝句","c":["石鼓镌功元自缺，秦碑颂德久应讹。","一时篆籀今谁解，白发江南玉雪坡。"]},{"t":"苕溪陆文宝挟笔过云间持卷求余言而一时缙绅之户不啻百篇有论笔法自赵松雪用落墨而始废者有为笔卦者近世肤学小子率意妄作类如此可叹也已因赋五绝 其五","f":"七言绝句","c":["谩秃霜毫临北海，更求雪茧写兰亭。","也知不改无盐陋，浪抹青红斗尹邢。"]},{"t":"次韵邵筼谷暮春三首 其一","f":"七言绝句","c":["处士浑同郑子真，水南结屋与山邻。","已从竹笋生旁舍，不遣桃花误世人。"]},{"t":"辛亥七夕五首 其三","f":"七言绝句","c":["五夜天边辍凤梭，长生殿里望星河。","玉环他日无穷恨，更比牵牛织女多。"]},{"t":"读胡笳曲","f":"七言律诗","c":["百年已到甲辰终，休倚山河百二雄。","八骏何劳巡海上，一龙今见起江东。","专门学士空谈道，仗钺将军竞策功。","忍听胡笳旧时曲，此身飘泊叹秋蓬。"]},{"t":"奉化李公复祖母沈氏年二十生子七月而寡既长沈为娶兄之女为妇生二子亦寡长即公达次公复二母今皆已老号双节堂赋","f":"七言古诗","c":["凤觜鸾胶难续弦，双龙镜破难再圆。","阿婆二十已守节，新妇哭夫方少年。","大儿娇啼母心苦，小儿十月安知父。","破窗风雨来早秋，夜绩灯前共相语。","山头松柏摧为薪，山前翁仲亦成尘。","红颜憔悴垂白发，生死不惭泉下人。"]},{"t":"水龙吟 春思","f":"古风","c":["楚天归雁千行，一书不寄相思苦。","匆匆过了，踏青时节，更愁风雨。","燕子黄昏，海棠春晓，几番凄楚。","问谁能为写，重重别恨，算除有、江淹赋。","尚记银屏翠箔，抱琵琶、夜调新谱。","芳年易度，沈腰宽尽，白头如许。","弱水三千，武陵一曲，重寻何处。","奈无情杜宇，年年此日，到淮南路。"]},{"t":"送王克让归湖南侍亲并柬李中卿县丞","f":"七言律诗","c":["五两风生楚客归，梦魂先已到庭闱。","九疑舜冢苍梧野，三国周郎赤壁矶。","天地茫茫人自老，古今历历鸟空飞。","若逢李白烦相问，别后平安一字稀。"]},{"t":"杂诗七首 其一","f":"五言古诗","c":["我闻度朔山，蟠桃何郁郁。","千岁才一花，结子复何日。","食之云不死，敷腴反枯质。","跨鹤凌九天，将共五龙匹。","谅非广成子，欲待安可必。"]},{"t":"杂诗七首 其二","f":"五言律诗","c":["祖龙帝六合，不暇谈黄虞。","且复求神仙，入海窥方壶。","置酒阜乡亭，起然忘故都。","空留赤玉舄，安期今有无。"]},{"t":"杂诗七首 其三","f":"五言古诗","c":["种桑饲春蚕，桑叶何沃若。","种瓜待秋摘，瓜蔓何漠漠。","春秋各有获，在野犹可乐。","君看金张馆，草深狐兔宅。","勿较是与非，看云倚高阁。"]},{"t":"杂诗七首 其四","f":"五言古诗","c":["大哉龙门树，郁郁上参天。","根株岂不固，小草还相缠。","蓐收行素秋，凄其风露寒。","病叶危欲堕，朔禽亦已迁。","朝华痛夕陨，掩泪复何言。"]},{"t":"杂诗七首 其五","f":"五言古诗","c":["结束将何之，龙门访陈迹。","弁途及良辰，置酒别亲戚。","迢迢越千里，人马疲登陟。","大江不可济，天方限南北。","怅然回吾驾，去从山村适。"]},{"t":"饮酒 其一","f":"五言古诗","c":["六龙骤朝暮，百川无西回。","所以陶阮辈，落魄事酒杯。","共尽生者乐，勿为死者哀。","借问东方朔，桃花今几开。","秦皇及汉武，求仙亦荒哉。","弱水三万里，何处登蓬莱。","与君且一适，随意坐苍苔。"]},{"t":"饮酒 其二","f":"五言古诗","c":["坐看万古月，因思万古人。","万古人不见，万古月长新。","持酒劝我影，可以成主宾。","利剑不断愁，火药胡能神。","南阮与此阮，一富复一贫。","白骨俱化土，碧草空自春。","酒尽月欲落，狂歌惊四邻。"]},{"t":"乌龙井","f":"五言古诗","c":["曾饮乌龙泉，为爱乌龙井。","不辞登降劳，迢迢越南岭。","石散驼马群，树结龙蛇瘿。","遂坐泉上亭，聊以观我影。","岁久科斗灭，朝塞辘轳静。","徘徊不忍去，胜处心已领。","有约待春深，携客来煮茗。"]},{"t":"白水村","f":"五言古诗","c":["朝发白水村，风帆健如马。","行人互先后，去鸟纷上下。","白云生远岑，青天入平野。","依稀林木外，幡幢见精舍。","河边四五家，犹是鸡豚社。","我游亦已屡，把酒心莫写。","欲访桃花源，悠悠愧渔者。"]},{"t":"九日游鹰窠山","f":"五言古诗","c":["忽忽已九日，出门净无泥。","地偏寔斗绝，有山如会稽。","宾客后杂遝，仆夫各有携。","天风海上来，我马骄且嘶。","坡陀出险径，窈窕遵回溪。","前登郯家岭，始觉华盖低。","作者四五人，更托千层栖。","日午扣其户，不愁苍耳迷。","欲俛栖鹘巢，上陵万丈梯。","岂但畏猛虎，彷佛闻天鸡。","共燕修竹林，落日犹在西。","相看且一笑，四郊多鼓鼙。"]},{"t":"两河兵兴京师乏食民部尚书曹公德基出使三吴因纪其事","f":"五言古诗","c":["东南寔天府，岁漕三百万。","龙城积红腐，虎士班白粲。","焉知十五年，不解戎马乱。","采稆以为食，屯集成背叛。","至今两河地，僵尸作京观。","诸侯土贡绝，君忧切宵旱。","尚书出宣旨，跋涉非所惮。","国无九年蓄，志士常切叹。","空山独病卧，无书托飞翰。","中宵望使星，迢迢阻河汉。"]},{"t":"送金子厚归杭","f":"五言古诗","c":["故人金子厚，四十犹落魄。","扁舟溯江涛，访我黄山脚。","我惭老穷经，春蚕空自缚。","羡君神仙姿，翩翩九皋鹤。","不上光范书，暂卖壶公药。","高视万物表，道尊卿相薄。","山中十日留，穷天慰离索。","联诗出险语，酌酒成大噱。","东风碎河冰，归思中夜作。","鹅黄催柳条，椒红折梅萼。","重来未有期，惜别中颇恶。","俱宜慎出处，一瓢宁改乐。","飞鸿正南来，有书幸相托。"]},{"t":"泮池荷花","f":"五言古诗","c":["荷生泮池中，云覆明镜密。","清飙激回芳，浊水钟妙质。","凝碧洗朝雨，嫣红酣落日。","折茎或牵丝，食薏时摘实。","犹疑南浦泛，谅匪东林匹。"]},{"t":"戏赠李焕章","f":"五言古诗","c":["善博不成枭，善射灴中鹄。","及此感衰谢，世道方局促。","皎皎明月珠，如何混鱼目。"]},{"t":"食糟蟛蚏","f":"五言古诗","c":["江乡富鱼错，有物小而铠。","天晴走白沙，月暗来沧海。","空怜朔客疑，尚被南翁采。","刀斧不足膏，瓶罂遂俱逮。","失身酒泉流，举族糟丘醢。","对此汝哀汝，生食之岂罪。"]},{"t":"乙巳除夕","f":"五言古诗","c":["春风何处来，庭草忽已碧。","不惜流年驰，感此千里客。","管葛树功名，孔颜丰道德。","低回违宿愿，览镜双鬓白。","高堂夜张筵，新酒行琥珀。","得失谁与论，浩歌永今夕。"]},{"t":"题尚北海听雨轩","f":"五言古诗","c":["海门飞雨集，高栋有馀清。","斜侵虚壁过，远逗大江平。","檐花朝乱滴，庭叶夜俱鸣。","凉知苏道暍，润喜濯园英。","微茫空暝色，萧瑟自繁声。","飞盖阻来客，独坐轸深情。"]},{"t":"槜李郭宗夏兄弟五人友爱尤笃后值兵变东西散处宗夏思之为作五雁图赋诗","f":"五言古诗","c":["五雁何翩翩，饮啄同清池。","失路在中道，饥寒不相知。","昔为八龙聚，今作四鸟离。","惊飙广漠至，十月百草衰。","天高羽翮短，苦受胡鹰欺。","上林岂不广，念汝归何时。","管蔡兴流言，坐使君臣疑。","京城死大叔，寤生手刃之。","淮南歌尺布，千岁有馀悲。","东阿苦不容，七步咏然箕。","骨肉成虎狼，所争毫与釐。","我观五雁图，为继鹡鸰诗。"]},{"t":"次韵张希载雨中书怀","f":"五言古诗","c":["夏雨盈百川，高岸复深谷。","鳞鳞低度云，汨汨驶流瀑。","口营叹翔鹳，臆诉哀病鹄。","征夫在中道，少妾乱心曲。","更希若木光，照此车下独。"]},{"t":"凌霄花","f":"五言古诗","c":["木椿何亭亭，相传五百载。","陵苕亦扬芳，灼芍藉光彩。","感彼径寸苗，附此千尺乔。","同心无异族，假翼在崇朝。","朱茔耀白日，翠蕤牵清飙。","缠绵欣有托，淖汋静无妖。","坐愁节序易，颜色易俱凋。"]},{"t":"丙午七夕 其一","f":"五言古诗","c":["生寡糜禄情，不复就羁绁。","曝衣记蚤秋，置酒陶嘉节。","曲无二八舞，味荐水羞洁。","轻纨怯迅飙，明烛欺初月。","林鸟戾且飞，玄蝉凄更咽。","主宾聊晤语，儿女空感别。","耿耿候双星，漏终河汉没。"]},{"t":"丙午七夕 其二","f":"五言古诗","c":["芳燕乐清夜，浩歌悲暮年。","故国山河迥，殊方斥堠连。","友于成契阔，宾客暂周旋。","念旷情易洽，怀归思更绵。","列星稀未出，金波澹始弦。","落烬秉残蜡，繁吹起终筵。","后会复经岁，举爵共无眠。"]},{"t":"读书堆","f":"五言古诗","c":["泊舟亭林湖，突兀空王宫。","当时读书处，鸟雀呼秋风。","前瞻两金山，抃舞波涛中。","眷兹一篑力，克配千仞崇。","恐有文字藏，中夜飞白虹。","荒哉梦中语，且复诳儿童。","我亦有书癖，五经老未通。","草堂可遂结，当作两希冯。"]},{"t":"登积庆寺阁","f":"五言古诗","c":["层楼何巍哉，金碧中突兀。","俯见百里外，山断平野阔。","青天倾东南，伯气忽已灭。","忆作皇庆初，六合既同辙。","眷兹葭菼中，鬼二成观阙。","我来属丧乱，彷佛大业末。","奔窜虽云苦，登眺亦颇悦。","居庸不可见，太华才一发。","故乡今何如，路险复霜雪。","苍苍白日晚，目送归鸟没。"]},{"t":"名都篇","f":"五言古诗","c":["赵魏天下枢，相从多贵游。","起家至千石，结客倾五侯。","光辉喧戚里，意气动神州。","蹋鞠东城罢，张筵西第留。","倒海为我饮，兼山为我羞。","妙舞呈楚艳，清歌列齐优。","共称齐三寿，惟愿乐千秋。","福盈知所戒，宠极惧生尤。"]},{"t":"兰","f":"五言律诗","c":["丛兰何青青，罗生满中泽。","阿那风叶翻，葳蕤露房柝。","芳洁终自持，光荣谅谅饰。","勿为时所化，岁晚同荆棘。"]},{"t":"对月怀邵筼谷","f":"五言古诗","c":["携酒东园游，望舒已就缺。","促席尊未空，方舟君夜发。","东西耿相望，复对三五月。","阶前皓彩盈，窗下朱荣歇。","同袍成异县，思逐回风结。","异县非千里，邈若胡与越。","吴趋唱谁和，楚调哀自辍。","感此百年客，世故怕羁绁。","荣华一朝露，采秀亦可悦。","归濯清江流，冥栖保芳洁。"]},{"t":"怀夏士文","f":"五言古诗","c":["楼船昔西迈，霜降百草衰。","日月一何遒，子行忽经时。","众绿荣枯条，谷鸟鸣且悲。","豺虎塞道路，郁郁劳我思。","我思晨复夜，谅匪渴与饥。","行人发吴门，消息安可知。","且复慰其私，岂敢言是非。","惜哉无六翮，念子何当归。","云中有黄鹄，会见东南飞。"]},{"t":"题诚道原潇湘八景 其一 潇湘夜雨","f":"五言律诗","c":["江空夜如何，急雨千里洒。","水生黄陵庙，云暗苍梧野。","鼓瑟来湘灵，移舟近渔者。","重华不可见，竹上泪如写。"]},{"t":"题诚道原潇湘八景 其二 洞庭秋月","f":"五言律诗","c":["轩辕已上天，弓剑人间留。","唯馀万古月，长照洞庭秋。","君山云气灭，水合天光流。","勿遣金虾蟆，脱归千文湫。"]},{"t":"题诚道原潇湘八景 其三 渔村夕照","f":"五言律诗","c":["羲和忽西匿，阡陌散馀辉。","澄江度双翼，遥岑明半规。","孤烟野店起，归人一何迟。","遗荣羡父老，衰白无所悲。"]},{"t":"题诚道原潇湘八景 其四 江天暮雪","f":"五言律诗","c":["曾云起北渚，万象入鸿濛。","散漫飞轻雪，低回逐劲风。","思群无牧马，失侣有征鸿。","泛泛独垂钓，扁舟黄发翁。"]},{"t":"题诚道原潇湘八景 其五 平沙落雁","f":"五言律诗","c":["群雁来衡阳，亦如万里客。","日暮空俳佪，欲去饥无食。","兼葭暗汀洲，惊飙吹倦翼。","上林须春归，宁为罗网得。"]},{"t":"题诚道原潇湘八景 其六 山市晴岚","f":"五言律诗","c":["山光洗新黛，好雨不崇朝。","日迟蒙薄雾，天近霭微霄。","茅茨犹隐约，金翠郁岧峣。","前峰恐无路，有客度危桥。"]},{"t":"题诚道原潇湘八景 其七 远浦归帆","f":"五言律诗","c":["楚客发天际，扬帆入三湘。","回首青山远，忽已过涔阳。","晚树何历历，归思浩茫茫。","永愧波上鸥，渔父共相忘。"]},{"t":"题诚道原潇湘八景 其八 烟寺晚钟","f":"五言律诗","c":["清钟象蒲牢，夜触海底鲸。","海鲸岂有意，蒲牢本无声。","二物偶相值，坐使百里惊。","高僧定初起，月上空山明。"]},{"t":"丙午冬十一月辟乱亭林明年春馆于扬溪邵筼谷氏四月一日乡兵复大起合境之人鸟惊麇窜不知所届余亦去而从之既定而返因写怀云","f":"五言古诗","c":["茫茫新战场，白草迷四顾。","烽火连石门，我归亦无路。","穷鱼久在辙，惊鹊空绕树。","故园今何如，犹思读书处。","近闻遭杀戮，岂复有亲故。","安得附晨风，从之西南去。"]},{"t":"出璜溪","f":"五言古诗","c":["白首事章句，不登金马门。","空名苦为累，遂枉三聘烦。","一瓢虽屡空，五鼎非所存。","愿偕田父游，卜宅溪南村。","霜寒收杮栗，日暮收鸡豚。","去矣从本性，得与巢许论。"]},{"t":"归崇德西曹村","f":"五言古诗","c":["田翁驩我归，假我茅堂居。","石桥跨流水，夏木友四隅。","风蝉聒旦暮，亦有安巢乌。","览之为欣然，息驾歌唐虞。","寄我六合内，何地非其庐。","荒哉百年客，千金营一区。"]},{"t":"迁居","f":"五言古诗","c":["我贫无定居，一岁三四迁。","破庐仅蔽席，于生已为宽。","南邻盛车马，北里矜绮纨。","高楼出云雨，一一居神仙。","何异玉台秀，四时游且盘。","念力守穷栖，去去非所安。"]},{"t":"立秋日","f":"五言古诗","c":["叶落天始秋，一气自回薄。","郁蒸变凄厉，衰它独先觉。","行云翳白日，向夕风雨作。","所欣同一溉，流水百道落。","园葵遂会滋，可以供我酌。","白发西邻叟，相过慰漂泊。","贻我酒两鸱，对之中颇怍。","高歌尽君触，从人诮徐邈。"]},{"t":"夏夜","f":"五言古诗","c":["惮暑夕屡兴，飞虫亦纷拂。","玉宇旷无邻，星河阻灵匹。","眷兹朱火中，悼彼青阳失。","旧知伤已逝，新欢邈难即。","虫虫气如焚，惕心心为怵。","惧先霜雪交，易变蒲柳质。","彷徨不能寝，坐候东方日。"]},{"t":"丁未重午","f":"五言古诗","c":["世乱无安宅，尽室久在路。","山蜩始一鸣，海燕时双去。","已叹朱户非，不见龙舟渡。","采药讵能寿，酌酒聊自豫。","四时倏相代，百岁同为寓。","日长坐风檐，更读离骚赋。"]},{"t":"题绿绮轩","f":"五言律诗","c":["朱丝操白雪，白鹤舞婆娑。","犹闻广陵散，不废懊憹歌。","风来茂花树，月落洞庭波。","不见古人久，焉知古意多。"]},{"t":"仲冬秋泾客舍","f":"五言古诗","c":["水涸天始寒，爽气薄絺绤。","空林无荣木，斥卤草俱白。","纷纷各有营，驱马不得息。","嗟予亦何者，惨惨长路侧。","饥寒恒累仄，岂不厌所历。","北风来广漠，徒御皆少色。","踟蹰但回顾，白日忽西匿。","山川莽悠悠，沿洄良未极。","索群中野兽，逐侣南去翼。","谁能独无情，归哉山中宅。"]},{"t":"皂林驿","f":"五言古诗","c":["朝发白水村，夕次皂林驿。","水腥无饮马，林墨有归翮。","昔时兵交地，白骨如山积。","万灶今已夷，风亭焕新饰。","居人尚星散，父老悲故迹。","团团关山月，夜逐南征客。"]},{"t":"游仙诗三首 其一","f":"五言古诗","c":["巍巍阆风台，层构切青霄。","一气存太始，三神建高标。","天风翼芝盖，仙曲和箫韶。","左携赤斧游，右御山图朝。","上帝颔其颐，元君目相招。","富贵一脱屣，于焉恣长谣。"]},{"t":"游仙诗三首 其二","f":"五言古诗","c":["寸田何茫茫，其广周九野。","超然凌昆崙，银河夜西泻。","高厉风尘表，日月乃在下。","神官役鬼工，楼观丹青假。","勾陈与玄武，卫此神明舍。","麻姑别千霜，岂是得道者。","不见海三枯，白发徒盈把。"]},{"t":"游仙诗三首 其三","f":"五言古诗","c":["景风扇玄圃，漠漠琼花开。","乎美天上月，夜宴九成台。","盘行五色芝，酌以紫霞杯。","黄屋岂为贵，秦政亦荒哉。","浩然中独存，万象方胚胎。","纷纷梦玄驹，生死益堪哀。"]},{"t":"丁一鹤诗","f":"五言古诗","c":["大道日已芜，游谈纷琐琐。","韩非不得死，商鞅终梯祸。","伟哉高世士，结屋青山左。","年来颇得道，已觉初心果。","朝漱玉池津，夜存金鼎火。","御气超六虚，万物真蜾裸。"]},{"t":"采芝生诗三首 其一","f":"五言古诗","c":["功名不可恃，利禄恒为愆。","举世纷蚁集，伊人倏鸿骞。","十年不出户，上友绮与园。","金芝敷九葩，煌煌生石间。","朝阳晞宿露，光辉一何鲜。","采之备服食，度世希神仙。","永谢城市人，振衣百尺巅。","黄虞怅已远，肆志独超然。"]},{"t":"采芝生诗三首 其二","f":"五言古诗","c":["采采复采采，相与登高丘。","可以充我虚，五鼎何足侔。","茂陵岂识道，且从方一游。","徒闻甘泉产，更入蓬莱求。","白日忽已暮，悲风来素秋。","未若幽居子，不怀四海忧。","清节尚巢父，素心追许由。"]},{"t":"题夏颐贞西畴草堂","f":"五言古诗","c":["九山惟凤皇，突兀尊中卣。","山断忽平野，四水东南流。","海潮日夜至，新沙成故洲。","爱此斗绝境，遂与长沮游。","蒺藜苦满道，相率开西畴。","俗类桃花源，无历知春秋。","风寒禾黍熟，雨多桑柘稠。","土芝颇益气，玉延亦可羞。","过从有耆老，请谒无王侯。","四时共相保，千岁非所忧。","如何万里客，日暮行未休。","骑虎不得下，短衣归饭牛。"]},{"t":"久客始归寓井西旧宅述怀","f":"五言古诗","c":["在路日思归，已倦风水艰。","前经石门店，喜见西南山。","忆我初去乡，忽忽三十年。","儿童尽成老，此邻无复存。","阡陌迷东西，甲第空毁垣。","秋风落古木，方池荣夏莲。","倏忽惊世换，岂独遇神仙。","萧萧井西宅，白昼唯高眠。","所欣无维执，贫贱何足叹。"]},{"t":"晨兴在殳山作","f":"五言古诗","c":["夜雨四檐纪，坐待扶桑暾。","天高无馀滓，初景方宴温。","黄鹂萃霜木，白雁来寒门。","所欣居处幽，已忘趋走烦。","时枉道人过，或逢田父言。","伤哉乱离后，衣冠今几存。","赋敛日已亟，何地为桃源。","结茅向绝逆，牧豕学公孙。"]},{"t":"钱彦彬抄诗为赋","f":"五言古诗","c":["好古思古人，古诗朝暮读。","澹洎玄酒味，和平绿琴曲。","古人乞白骨，古意不谐俗。","已叹知者稀，古泪空满掬。","钱起亦敦古，其人美如玉。","昨者忽相过，大雪山中宿。","不知破砚冰，抄诗夜然烛。","谅非鲍谢才，可继曹刘躅。","听之讵能欢，旧业且当束。"]},{"t":"拟出塞曲 其一","f":"五言古诗","c":["翩翩荆扬士，结束赴幽州。","将军岂乐战，匈奴为我雠。","已通大月氏，更取乌珠留。","驱马白狼北，洗兵青海头。","归来饮高庙，庶雪平城羞。"]},{"t":"拟出塞曲 其二","f":"五言古诗","c":["早从汉捕虏，万里唯一身。","军中已三年，苦乐安可陈。","但见陇底雪，不识陇头春。","北风利刀剑，肌肤皆尽皴。","天王正开边，讵恤中国民。"]},{"t":"赴召留别诸友","f":"五言古诗","c":["用世非拙迂，白首在山林。","诗书况久辍，礼乐非所任。","王事忽相縻，遂令违我心。","迢迢适西道，恻恻辞东岑。","中田泽雉雊，古木鸧鹧吟。","所亲亦胡越，耿耿辰与参。","愁来一回首，涕下徒沾襟。","终当返田里，灌园希汉阴。"]},{"t":"送吴浚仲","f":"古风","c":["弱冠知君名，王十始逢君。","南宫托同宿，十明披清文。","及我备修纂，缺近幽兰芬。","兹言归故乡，告别那忍闻。","甡甡中林鹿，犹能念其群。","况我同心友，去住从此分。","夜度浙江水，朝看天姥云。","春禽正??，夏木方欣欣。","安得遂同载，归偶沮溺耘。"]},{"t":"六月十五日夜坐明德堂","f":"五言古诗","c":["大火直初昏，回飙荐微爽。","行遵曲池静，坐荫华构敞。","天高积阴散，水明圆魄上。","翩翩去鸟迅，唧唧砌虫响。","胡为京国滞，屡乖林壑赏。","吴中有莼鲈，吾当理归鞅。"]},{"t":"出都门一首寄张孟兼主事","f":"五言古诗","c":["日落宿都门，鸡鸣发淳化。","城南夜来雨，连山色如赭。","青松夹高岗，烟火通旅舍。","到家须十日，畬田熟秋稼。","如何山巨源，未知嵇叔夜。","野鹤终去人，疲牛岂胜驾。","寄书谢所亲，吾今老林下。"]},{"t":"辛亥初度日偶成","f":"五言古诗","c":["吾生本如寄，有酒还自酣。","岂待三宜休，已知七不堪。","陶泓且当传，孔方安可谈。","触网笑神龟，束身悲老蚕。","倘能从兹去，卜宅南山南。"]},{"t":"独酌","f":"五言古诗","c":["行军已六九，发脱身渐羸。","不及桃李花，遽成莆柳衰。","贵贱必同尽，造化宁吾私。","徒闻王子乔，何处求安期。","区区营丹砂，贪生无乃欺。","今朝欣无事，酒熟当自持。"]},{"t":"孤松","f":"五言古诗","c":["青松类贫士，落落惟霜皮。","已羞三春艳，幸存千岁姿。","蝼蚁穴其根，乌鹊巢其枝。","时蒙过客赏，但感愚夫嗤。","回飙振空至，百卉落无遗。","苍然上参天，乃见青松奇。","苟非厄冰雪，贞脆安可知。"]},{"t":"壬子秋七月一日与郭文伯饮入于朱弘道竹所是日大雨拟苏州","f":"五言古诗","c":["残暑尚为厉，客坐三四迁。","青山一雨过，虚室夜脩然。","欣与公子酌，语契中颇宣。","虽无丝与竹，庶罄宾主欢。","所贵相知深，岂惟怀一餐。","尊浮玉粒腻，炬拆金葩圆。","厌厌咏露斯，会面良已艰。","天明即鸿燕，西望独悁悁。"]},{"t":"送钱公择还象山","f":"五言古诗","c":["金陵一杯酒，送子归海隅。","五月南风正，荷花满镜湖。","登堂酌春酒，上奉双亲娱。","但惜千里别，莫赠鲛人珠。","虽仝天地间，一旦具越殊。","皎皎渥洼子，翩翩丹穴雏。","怅然不得从，远望白云孤。"]},{"t":"题听雪斋拟孟郊","f":"五言古诗","c":["霆轰急雨泻，石斗冲波荡。","百族巧鸣春，络纬催秋纺。","讵知空山夜，听雪乃真赏。","病骨僵如蝇，残灯虚虚幌。","积玉呈幻质，潜韶泄微响。","一气变鸿濛，五音归惚恍。","神清已无梦，理悟宁有象。","苦寒不可禁，更被王恭氅。"]},{"t":"梦游澄林","f":"五言古诗","c":["我梦游澄林，方舟坐垂钓。","一水穷萦回，三峰隐奔峭。","娟娟碧筱合，灼灼朱葩耀。","残雨趁回风，断云通返照。","林昏野老炊，溪动寒女漂。","平生爱桃源，何年陡员峤。","永惭白发蒲，起应金门诏。","犹思洗药处，空歌采菱调。","一鹤已与讥，九龙那免诮。","觉来复京华，语儿成一笑。"]},{"t":"杨贞妇王氏诗","f":"五言古诗","c":["石上有琅玕，孤生何猗猗。","婉彼深闺秀，笑语间且仪。","荣华谅未晚，芳洁当自持。","玉镜一朝委，相求岂无媒。","冰泮时当归，遥峰翠新拂。","行行别父母，遂居君子室。","君子官已崇，新欢鼓琴瑟。","如何事前驱，中道永相失。","东家有宋玉，西家有王昌。","皆知慕明艳，讵忍隳太纲。","露多焉能污，江永不可方。","贞心耀白日，峻节厉秋霜。","泣淡欲成河，捐躯遂如墓。","宁同陌上花，誓比山头树。","织绮献秋切，条桑事春务。","向非厄彊暴，岂知金石固。"]},{"t":"送王公勉赴沁水教谕","f":"五言古诗","c":["清商陨一叶，白下未知秋。","倦鸟息高荫，潜鱼依弱流。","君子方北首，山河阻且脩。","岁久衣尽缁，驱车良未休。","我无双明珰，何以结绸缪。","怅焉隔千里，白云空悠悠。"]},{"t":"题金德俊葵轩","f":"五言古诗","c":["结庐在林屋，所欣知者稀。","南风应蕤宾，我圃日芳菲。","负杖观其生，草多露满衣。","有葵独倾阳，岂愿回清辉。","清辉虽不照，物性谅无违。"]},{"t":"礼部员外张惟中七月十二日暮归赋诗入韵知者自尚书牛公以下凡若干人夫汉谣魏体互有不同巧于状物者过丽切于言志者怕直惟中退食之顷率尔成章且不以私而忘公情与景俱至已予因续众作之后凡器不足以谐空桑也","f":"五言古诗","c":["秋至星火流，病觉中岁剧。","成均忝分教，才非一狐腋。","日入欣暂休，野老或争席。","清谈杂虚无，以永风月夕。","百年会有尽，富贵非所适。","鸣虫亦知候，倦鸟思假息。","脱冠已童然，如何拘百役。","酒醉不复言，道固存目击。"]},{"t":"秋怀 其二","f":"五言古诗","c":["黄鹤日千里，潜鱼必深池。","蠢兹橘中蟊，化蝶俄天飞。","翩翩苦不已，倏忽胶蟊丝。","两翅既摧折，何日回枯枝。","非才慎所处，富贵亦何为。","且尽一杯酒，物我共忘机。"]},{"t":"题画竹","f":"五言古诗","c":["京朝非素心，林壑契玄赏。","读书甘寂莫，密竹更萧爽。","冲人虎豹经，闭刀蟏蛸网。","寒梢朽不蠹，野笋苞初长。","风生回鹤梦，月出闻猿响。","如何犹恋禄，厩马存病颡。","相期结二仲，兹焉共来往。"]},{"t":"送黄仲篪上官槜李","f":"五言古诗","c":["严霜戒秋杪，百草俱已衰。","子别何匆匆，一尊聊共持。","今晨白门道，后夜沧海湄。","长歌独慷慨，健步何逶迤。","古来声利场，日出纷火驰。","进非才不任，退亦分所宜。","吹竽我岂滥，售璞人皆嗤。","峻节当自厉，坦途方在兹。","从容有新语，千里慰相思。"]},{"t":"次韵张师广助教登雨花台 其一","f":"五言古诗","c":["行行出城南，登高望三丘。","雉堞壮天居，宫殿若云浮。","星分斗牛野，水合江汉流。","苍然淮上山，聚米当马头。","气已无朔漠，人今冠中州。","慷慨忆当时，远近开朱楼。","仙人翠羽帐，王母珊瑚钩。","貂蝉霭七贵，车马从五侯。","光辉互照耀，气意何绸缪。"]},{"t":"次韵张师广助教登雨花台 其二","f":"五言古诗","c":["皇威复禹迹，风气移荒陬。","千屯夹虎士，万斛回龙舟。","将军卫霍功，相国房杜谋。","我来览奇观，发兴属清秋。","已将函谷并，遂与洛阳侔。","所悲迫衰谢，蒙汜安可留。","目送桃叶远，水深凫雁洲。","清谈哂诸老，匡时忘远犹。","庶穷入极旷，慰此千里游。"]},{"t":"题朱孟辩层峦图","f":"五言古诗","c":["叠嶂何崔嵬，远近皆可数。","不学王宰迟，弃墨如弃土。","林藏风雨黑，石戴冰雪古。","初疑造化钟，已觉精灵聚。","遥思两山下，流泉细通圃。","茅屋今何如，人去苔生户。"]},{"t":"送盛孔赴淄川丞二首 其一","f":"五言古诗","c":["天寒北风利，有客赴临淄。","临淄古大国，山川何逶迤。","小白相夷吾，尊周攘四夷。","田单守即墨，一日走燕师。","二子不复见，名今千载垂。","为我吊精魄，伯功未可卑。"]},{"t":"送盛孔赴淄川丞二首 其二","f":"五言古诗","c":["魏有径寸珠，守境无檀子。","照车十二乘，何如照千里。","世乏威王贤，孰知天下士。","所以饭牛儿，商歌中夜起。","徒求南海产，半触蛟龙死。","异才何代无，纠纷今可理。"]},{"t":"题上虞柳机仲朝晖轩","f":"五言古诗","c":["日车上搏桑，曈曈鸡子黄。","遥夜忽复旦，仰瞻有启明。","征夫起当发，宿鸟号且翔。","城郭互参差，曲户通天光。","空照堂中人，岂销发上霜。","竹枝自垂荫，萱草亦扬芳。","此心谅已短，此恩一何长。","欲报固无极，念之安可忘。"]},{"t":"雨中漫兴","f":"五言古诗","c":["端居少宾客，鸟迹偏阶除。","夏雨后兼旬，众木青扶疏。","金石何必陈，此乐当何如。","永怀漆园吏，相去千载馀。","万物虽一体，忽若胡越殊。","人苟不知我，我岂能知鱼。"]},{"t":"临川饶孟持所居西轩有先大父所植杏一株今百年矣幸不剪于兵火因筑亭于旁名杏庭云宋景濂作赋予赋诗","f":"五言古诗","c":["结构非壮丽，可以乐晨昏。","仰荫百年树，深蟠千岁根。","粲粲朱葩敷，离离青子繁。","秀出风烟表，润含雨露痕。","戎马方纵横，境内悉崩奔。","桃李摧为薪，荆棘翳高门。","荣华谅难恃，尚见文献存。","未拟匡山田，讵论曲江园。","读书弦素琴，命客置芳尊。","永言益封植，祖德慎无谖。"]},{"t":"古意三首 其一","f":"五言律诗","c":["春风天上来，蒲城红与紫。","如何朝暮间，飘落随流水。","堂前两冬青，霜雪犹不死。","向来三月时，谁言及桃李。"]},{"t":"古意三首 其二","f":"五言律诗","c":["对酒发长歌，歌长苦难续。","浮云空自行，白日安可逐。","黄河走东海，千里才一曲。","奈何人之心，顷刻有翻覆。"]},{"t":"古意三首 其三","f":"五言律诗","c":["六国多好士，堂上各三千。","所亲苟不慎，祸福怕相因。","李园贼黄歇，冯驩复田文。","种桃得秋实，蒺藜徒刺人。"]},{"t":"六月二日至临淮夜宿方丈敏东轩","f":"五言古诗","c":["北斗分四时，怕星自昏晓。","如何百年客，贵贱俱扰扰。","酒酣虚室卧，雨绝四山悄。","道冥天地广，身在风露表。","六合一何大，毫芒未为小。","宅神惟寂莫，适意忘缠绕。","朱丝竟谁赏，白发今已少。","永期江湖居，相亲有鱼鸟。"]},{"t":"送张思广归平阳","f":"五言古诗","c":["十月天地闭，北风河已澌。","送子千里道，太行极崔嵬。","日暮归鸟疾，雪深苍兕饥。","酌以一卮酒，为浣身上衣。","伐木还重赋，白驹不可维。","悠悠南北歧，恻恻劳我思。"]},{"t":"分题送友得忠孝庙","f":"五言古诗","c":["丈夫死殉国，于道讵非宜。","烈烈卞侍中，忍顾王室危。","枭獍敢为逆，我师焉可支。","跃马婴其锋，以肉充虎饥。","苦战既不旋，有子亦从之。","精忠贯日月，未惭马革尸。","至今石头下，尚使行人悲。","郁郁冶城山，秋风吹古祠。","送客远相过，慷慨伤我怀。","当时诸老臣，清谈竟何为。","酌酒酹英魂，忠孝以为规。"]},{"t":"池河驿","f":"五言古诗","c":["早发红心驿，日暮宿池河。","百里无人烟，狐兔马前过。","山明见野火，溪浅通微波。","却立时踯躅，前登益嵯峨。","北风何萧萧，尘埃衣上多。","下马留信宿，对酒一长歌。"]},{"t":"大枪岭","f":"五言古诗","c":["巍巍大枪岭，羊肠盘九曲。","深林野雉雊，短草豺虎伏。","行人疲不进，惨惨对僮仆。","下得仙居涧，始复就平陆。","一株罗浮苍，春深粲如玉。","五年怅不见，乞日开我目。"]},{"t":"滁阳驿","f":"五言古诗","c":["群山绕滁州，城郭带林壑。","岂惟居人稠，遂使游子乐。","苜蓿青满野，羊马盛幽朔。","固知英雄主，四方归大略。","回视清流关，往事殊可薄。","新花寒未开，细雪春犹落。","且持一斗酒，独与故人酌。"]},{"t":"猛虎行","f":"古风","c":["有虎有虎，在彼中野。","高步风生，何物敢侮。","以比直臣，独立无与。","前称长孺，后载文举。","亦有埋轮，复闻破柱。","为时所惮，豺狼气沮。","奈何今人，使我怀古。"]},{"t":"李氏三节妇行","f":"五言古诗","c":["赫赫陇西杰，奕叶何光辉。","一门见三子，不同乡里儿。","三妇名家姝，玉貌长蛾眉。","大妇居中堂，夜织流黄机。","中妇具朝餐，泉出江鱼肥。","小妇二十馀，金刀新制衣。","青松与女萝，百岁欣相依。","未及白头日，双凤俄分飞。","入房洗粉黛，岂复施珠玑。","盘龙掩明镜，宾鹤琴中悲。","生既不同室，死则须同归。","鸿雁犹有信，妇道安可暌。","残灯冬夜长，素月光徘徊。","共绩还共语，白玉当不灰。","有子官已高，少壮忽复衰。","丈夫少气节，恒惧白刃威。","女子乃如上，盐山同巍巍。"]},{"t":"述怀","f":"五言古诗","c":["浩荡三十年，如萍寄沧海。","起为太学师，一日扬光彩。","迢收赴中都，送客纷云蔼。","名惭相国知，礼感亲王侍。","徘徊未得去，忽复朱颜改。","诏许江南归，青山草堂在。","放浪黄牛村，犹瞻金马门。","适性讵非乐，扪心空自论。","田翁四五人，共忘乡相尊。","把酒酬殳基，白石今犹存。","天寒落松影，岁久生苔痕。","试求金光草，超然事幽讨。","依稀顾况台，寂莫钱王道。","东门叹黄犬，税驾胡不早。","长歌归去来，吾从鹿门老。"]},{"t":"梦游秦望山歌送客归越中","f":"楚辞体","c":["秦望何崔嵬，削如青莲开。","下临七十二湖之浩荡，上接三十六洞之萦回。","梦中夜渡浙江水，轻如鹤背乘风来。","欲求轩辕上天处，白云尚锁烧丹台。","徒知有弱水，安可睹蓬莱。","但闻松声万壑兮，夹飞湍之喧豗。","赤日惨淡而无色，复殷殷之雄雷。","踰千盘兮历百折，香炉玉笥左右列。","山中二女问何迟，桃花落尽燕支雪。","金鸡三叫失所在，惟想参差白银之观阙。","龙绡寄别泪，三载犹未灭。","有美一人兮佩珊珊，昨游吴门复东还。","余愿从而上下兮，叫安期于云间。","回首隔千里，可望不可攀。"]},{"t":"雪蓬小朵歌送奎方舟还灵鹫","f":"楚辞体","c":["蓬婆雪岭高崔嵬，横绝青山飞鸟回。","山中小朵更奇峭，石作莲花千叶开。","巨灵擘山断山脉，一峰夜向东南掷。","千秋乾竺空有名，万里峨眉尽无色。","攒青叠翠兮西湖，洞口白猿犹可呼。","咸和之年有慧理，卓锡尚爱飞来孤。","本杯高僧两眉雪，身如浊水清莲洁。","翻经石上不知年，桂子年年落秋月。"]},{"t":"京口王节妇歌","f":"古风","c":["大江如带从左来，金山焦山碧崔嵬。","风吹杨卷度江去，妾心如山不可回。","忆昔移所天，岂独甘守节。","两草方缠绵，那知中道诀。","玉琴不奏双鸳鸯，玉箫不吹双凤皇。","纺绩给朝暮，蛾眉忽成霜。","蟏蛸网素壁，燕子归空梁。","生乖同室处，死期同穴藏。","郁郁山头树，已见参天长。","白璧须恶玷，白丝须恶染。","边声乱胡笳，万古悲蔡琰。"]},{"t":"玉山窟儡歌","f":"古风","c":["玉山窟儡天下绝，起伏进退皆天机。","巧如惊猿木杪坠，轾如快鹃峰尖飞。","流苏帐下出新剧，河梁古别传依稀。","黄龙碛里胡雏语，李陵台前汉使归。","当筵舞剑不辟客，顿足踏地争牵衣。","玉箫金管静如水，西夏钿山相是非。","昔闻汉主出大汉，七日始脱平城围。","当时论功孰第一，木偶解走单于妃。","奇兵百万竟何事，将军赐级增光辉。","龙争虎战亦同幻，尊中有酒君无违。","呜呼在家双凤和我曲，玉斗碎落千珠玑。"]},{"t":"题子昂松树障子歌盖王成之所藏者纸尾云大德八年正月廿夜灯下书","f":"古风","c":["吴兴华法兼钟王，不独醉草过张旭。","既无河朔少年之沓拖，又无深山羽人之退缩。","故人相遇乞何夕，银烛吐光如月白。","手写青松障子歌，百金一子无所惜。","何物小儿憎妩媚，玉环飞燕皆倾国。","嗟我平生秃千兔，夜写蝇头愧无益。","王孙骑鹤去不还，日落太湖云气赤。","君家此木世希有，词翰风流与之敌。","纷纷真赝那足辩，珷玞敢厕连城璧。","勿同玉枕永和书，一閟昭陵永相失。"]},{"t":"题王立本山水图","f":"古风","c":["我有爱山癖，每欲名山去。","秦溪一日寄新图，歌枕高堂睹云雾。","何年王宰留真迹，青城天彭接太白。","金堂石室犹可识，大树小树参天直。","千盘百折分秋毫，木客时与行人遭。","一门通天剑阁险，三峡涨雪瞿塘高。","小舟如凫争入浦，呕哑卧听沝鸣橹。","拾遗近在浣花溪，却面龙湫结茅宇。","豺狼塞路何由通，采芝亦有商山翁。","安得相从向绝境，振衣千仞来天风。"]},{"t":"甲辰七月十三日书所见","f":"七言绝句","c":["行人渐稀日已没，星堕西南大口月。","一道馀光夜不收，青天万丈金蛇掣。"]},{"t":"题赵仲穆画马","f":"古风","c":["吾闻冀北之马如云照川谷，八尺飞龙在天育。","滦河远幸翠华迟，柳林大猎金鞍簇。","是时四海为一家，东踰日本西流沙。","拂郎近献两骕骦，不数郭家狮子花。","公子前身岂曹霸，一马真轻百金价。","黄金台上倦为客，白发江南随意画。","骝騧骃駓各不同，饮泉龁草落笔工。","君不见龙庭苜蓿与天远，何人更收青海骢。"]},{"t":"送王好问赴春官","f":"七言古诗","c":["君文空桑恊宫徵，我文凡器不悦耳。","早随举子踏槐花，曲江走马秋风里。","院门鱼钥晨未开，白袍鹄立三十士。","风檐落笔誇先成，食叶老蚕春乍起。","樗莆三叫不作卢，白首读书犹未已。","两河草动持干戈，圭星无光作者死。","五门下诏蒐遗村，四月文场酣战蚁。","先生有志复先登，软裘快马入居庸，得意看花丽春市。","上林赋就气凌云，我亦明年献天子。"]},{"t":"送文从周入京师","f":"古风","c":["文郎气如虹，北上何匆匆。","重经九折坂，复览百步洪。","日月回地底，山河极云中。","有书一万言，欲献明光宫。","蚩尤触山折天柱，百川乱流赤子苦。","龙骧未见下益州，虎旅犹闻驻灵武。","草白风骚骚，跋涉无乃劳。","骅骝识骏骨，鸑鷟非凡毛。","临岐更酌酒，飞雪落征袍。","何以致缒绻，绵带昆吾刀。"]},{"t":"张静婉采莲曲","f":"古风","c":["妾长平康里，能舞复能歌。","髻斜梳堕马，眉浅约弯蛾。","陌上游人顾，日前侯客过。","涂黄初拜月，拾翠欲凌波。","已知一身重，不受千金唤。","十五事秋娘，十六归羊侃。","愿妾比双莲，为君朝暮鲜。","君能重妾绸缪意，别起高楼大道边。","春乘油壁香车出，夜入流苏甲帐眠。","高楼下俯平湖阔，照妾浓妆并淡抹。","五月平湖水正深，荡舟相逐起双禽。","莫学藕丝容易绝，试将莲子托同心。"]},{"t":"出塞曲","f":"七言古诗","c":["七星昱昱大将旗，猛士百万皆熊罴。","迢迢远出雁门塞，汉虏相见还相持。","军中无粮杀牛马，夜得降人知众寡。","天山月黑潜度兵，飞箭著人如雨下。","捷书明日报甘泉，死者白骨归何年。","春风草绿秋风白，魂魄为君长守边。","五岳为城海为堑，天下人当亲弓剑。"]},{"t":"野中吟","f":"七言古诗","c":["野中古墓何累累，子孙已绝傍人悲。","送车百两喧鼓吹，却忆出祖东门时。","墓前青青春草没，墓下纵横狐兔穴。","昔年已见野人耕，今年复见邻人发。","千年髑髅出黄土，翁仲无言泣寒雨。","何时故物总成灰，犹有玉钗留半股。"]},{"t":"田家行","f":"古风","c":["田中八月红稻熟，田头黄雀飞且啄。","去年出走不得收，今年父子田舍宿。","夫妇小妇长裁衫，夜起剪乘饲五蚕。","不言画眉无宝镜，不恨梳头无宝簪。","稻登场，蚕在箔，新谷可舂丝可络。","赛神城南听神语，但祈无兵岁不苦。"]},{"t":"枢密院椽曹李至刚从帖木公守耽罗一年诏回京师遇风抵曹泾明年夏复蹈海北上诗以送之","f":"七言古诗","c":["白洋十月行人苦，北风簸浪鱼龙舞。","黑洋六月南风回，海客椎牛赛彭祖。","使者迢迢入帝畿，连艘夜发迅如飞。","六鳌尚戴三山起，一鹤初从万里归。","张仪虽困犹存舌，置酒都门歌激烈。","丈夫得官贵少年，腐儒穷经空白发。"]},{"t":"白茅歌美华亭丞盛彦忠","f":"古风","c":["山东未息马，山西尚挥戈。","急起州县丁，北开白茅河。","海风裂面天雨雪，山高水深不见月。","万人凿土如凿山，河边死者谁收骨。","白茅河成如白虹，百里直与昆城通。","将军不待驱鬼工，平地遂作鱼龙宫。","问谁爱民如爱子，华亭盛侯古莫比。","昔去今还悲复喜，非汝身为白茅鬼。","盛侯之德之水，千古万古流不已。"]},{"t":"送天台吴蟾友奉董宗师命主桐柏观","f":"古风","c":["天台之山四万八千丈，中有飞仙共来往。","东方未白天鸡号，扶桑赤日三更上。","山人曾识玉蟾翁，丹砂九返面如童。","吹笙醉跨千年鹤，朝上崆峒暮庐霍。","葛洪井西松树老，子晋台下桃花落。","日边人寄董师书，别我却入天合居。","麻姑相见已白发，蓬莱弱水人何如。","我亦张帆上南斗，餐霞有诀能相授。","青天更约借龙骑，福地应知今虎守。"]},{"t":"题子昂秋林早行图","f":"古风","c":["北上莫度河，龙门如天谁敢过。","西游莫趍蜀，瞿塘如马谁敢触。","大星未落月挂树，行人出门向何处。","日日西东往复来，青山不断天涯路。","天涯路险更无穷，破裘羸马怯秋风。","日高茅屋犹未起，愧尔山中白发翁。"]},{"t":"题赵秋江渔艇图","f":"古风","c":["朝渔江之南，暮渔江之北。","朝暮清江边，公侯不相识。","西塞山前秋日微，沧波浩荡钓船归。","老髯何来一相就，铁笛夜吹彭浪矶。"]},{"t":"小蓬壶歌","f":"古风","c":["君不见蓬莱方丈三韩东，上有飞楼涌阁何穹崇。","始知九州更在赤县外，弱水不与人间通。","赤麟伏可扰，白凤驯可笼。","瑶草四时碧，桃花千岁红。","卢敖一去已无迹，燕齐弟子徒相从。","铁厓老人有仙骨，七十复向云间逢。","高台剪断一曲幽，绝境银河倒挂双玉虹。","自非夸娥之神徙，其处安得缩地如壶公。","读书已去神禹穴，献赋不到明光宫。","麻姑相遇急洒扫，有酒莫使金樽空。","酒酣更呼双童为我歌，小海铁笛雷怒来天风。"]},{"t":"醉芙蓉叹","f":"七言古诗","c":["蜀江芙蓉四十里，花外楼台来江水。","蜀主龙舟八月来，日照千里锦云起。","一朵依稀武都女，雪色宫衣轻欲举。","已窃玄珠化水仙，不同右镜埋黄土。","朝妍夕态还相恼，传粉涂黄俱草草。","春风入髓犹未苏，丹砂换骨应长好。","凌波殿废花亦残，江上秋深风雨寒。","武林城南偶识面，把酒共看赪玉盘。","十年流落云间路，欲寻旧赏知何处。","芳心一点对斜阳，脉脉无言岁华暮。"]},{"t":"题赵处仁竹泉所","f":"七言古诗","c":["王孙宝玦已流落，九马不复归长安。","梨园歌舞入残梦，白屋无人空翠寒。","流泉汨汨如流乳，竹应笑歌成律吕。","酒酣濯足望洞庭，一片潇湘隔秋雨。","有鸟有鸟来丹山，羽衣五色朱其冠。","人间腥腐不足饱，食汝竹实饮汝湍，为汝一出三千年。"]},{"t":"用苏东坡先生韵赋竹轩","f":"古风","c":["朝饥不饱肉，朝寒忍看竹。","爱竹已成癖，尚胜桃李俗。","食笋冀生肥，我癖无良医。","箨龙未可斸，颇怪镵奴痴。","竹下哦诗空咀嚼，月明夜半来笙鹤。"]},{"t":"孙孝子歌","f":"古风","c":["乱兵夜入高邮城，孤儿失母号且行。","城边白刃耀霜雪，负母独出千人惊。","君不见鸱鸮生子食母肉，人间更有鸱鸮族。","儿知有母同死生，蓼莪已废犹能读。"]},{"t":"白苧词","f":"七言律诗","c":["江清月高夜未央，芙蓉半白微有霜。","天魔小队分两行，胡姬更劝葡萄浆。","酒酣回身入洞房，金炉火煖艺都梁。","愿君朝出夜饮酒，祝君千年万年寿。"]},{"t":"团扇词","f":"古风","c":["团扇何皎洁，误方雪与月。","雪当有时污，月亦有时缺。","妾恨似天长，君恩成两绝。","昨夜秋风长信来，星河已见西南回。","妾有新词讵堪写，夜扑流萤玉阶下。"]},{"t":"题倪云林画","f":"七言古诗","c":["云林先生老更迂，酒酣落笔元气俱。","沧洲赤县随意扫，不学徐熙没骨图。","沉犀石带波涛润，石上烟梢势千仞。","参天古木蛟龙僵，赤叶已脱荆门霜。","北风萧萧白日暮，相偶应知不相附。","丹山之羽何时来，会待春色阴厓回。"]},{"t":"折杨柳曲","f":"古风","c":["杨柳何青青，春风拂长路。","朝送行人归，暮送行人去。","行人南北无已时，折尽可怜无一枝。"]},{"t":"题王叔明茅山图","f":"古风","c":["一峰插天三万丈，众峰旁联不相让。","我行未尽天下奇，王宰写山工异状。","霭霭勾曲云，苍苍溧阳树。","天高去鸟没，日落行人度。","茅君已千年，浪忆烧丹处。","犹疑风雨夜，骑虎山头遇。","平生好山独未归，山中桃花如雨飞。","相从采术定何日，长向云间瞻翠微。"]},{"t":"秋夜长","f":"古风","c":["夜长河漫漫，嫠妇叹且泣。","落月当窗悬，回风寻户入。","新愁不可道，古恨无时断。","吾将叫重华于江之南，苍梧山高湘水满。","耿耿不寐，起观东方。","溥彼白露，降而为霜。","碧草无情，亦陨其芳。","安得不老，既玄而苍。","周公待旦，思兼三王。","伤哉何为，揽衣彷徨。"]},{"t":"远别离","f":"古风","c":["君不见青天之月，三五缺，三五满。","惟有别离愁，千秋万古何时断。","忆昨郎远行，城南柳飞絮。","迢迢出居延，匹马随都护。","今年得郎书，犹在天山戍。","黄河入大荒，白草迷归路。","夏日青无光，胡风起朝暮。","不若路旁尘，随郎马蹄去。","妾居但守节，郎去当封侯。","昔为白门燕，双栖江上楼。","今作陇头水，呜咽东西流。","时凭万里梦，夜到西梁州。","三十六部犹未灭，良人那得朝金阙。","可怜池上紫鸳鸯，白头生死不相忘。"]},{"t":"白雪歌","f":"古风","c":["昆仑火炎玉已灰，神为六叶空花开。","北风万里寒门来，一夜吹落金银台。","填埙委谷何皑皑，龙蛇僵缩虎豹哀。","洪流不作龙门雷，崆峒太白危欲摧。","将军夜出犹未回，马前一片大如杯。","山中野老居崔嵬，酌酒以匏烧芋魁。","安知银屏翠箔围白台，但歌田有百谷年无灾。"]},{"t":"送定南宗佐四明大慈寺","f":"七言古诗","c":["伏龙罗汉无人识，万里如云倏南北。","南北山川不可穷，云去云来自无迹。","朝辞凤阙向东湖，身乘一叶秋江芦。","东湖何处更求我，白云去尽青山孤。","开楼夜看山头月，月色湖光射冰雪。","四明太白相峥嵘，天地虚空一毫发。","老夫漂泊悲蓬根，相逢已契三生魂。","人开火宅不可住，他年听法来松门。"]},{"t":"青萝山房歌","f":"楚辞体","c":["仙华之山何崭绝兮，插天万仞青相磨。","山势东来忽平地，蜿蜒不断为青萝。","萝萝隐隐如崩石，夸娥负山山为析。","欲叫轩辕向何处，千古万古空遗迹。","玉女得道登云车，凌空直上太清家。","云车不复返，落尽金茎花。","风凄凄兮又下雨，行人惨兮子规语。","山回路尽或逢花，知是青萝山人结茅宇。","山人紫府神仙客，身今六十头尚黑。","胸蟠五色天女丝，手炼五色神娲石。","丝可为君成天章，石可为君补天隙。","一朝寘之白玉堂，青萝寂寂寒无光。","何年借我白石床，卧看明月来东方。","与君酌酒歌我曲，君归早访初平羊。"]},{"t":"题火龙烹茶图","f":"楚辞体","c":["松声忽作秋涛雄，铜龙吐火鳞甲红。","黄衣中使备玉食，泉出金沙甘露浓。","春风一旗色尚活，建溪山人雨前掇。","蓬莱殿里沃焦馀，玉盌兮沽侍臣渴。","名花唤起海棠魂，细叶未数丁香根。","宫中一日歌舞散，世上千秋图画存。","开元盛事何人省，书生亦解誇双井。","空中扫叶烧破铛，闭门读书秋夜永。"]},{"t":"齑瓮吟","f":"古风","c":["清江老人腹空洞，白首谈经耻无用。","酒酣入水问河神，乞我黄齑三百瓮。","平生不羡将军腹，冰壶先生真我族。","山妻日晏具朝餐，露叶霜根甘胜肉。","君不见海上巨族如公侯，诏书夜遣官兵收。"]},{"t":"耕乐吟二首 其一","f":"七言古诗","c":["南村北村喧仆姑，一雨已苏百草枯。","青稻如云不见涂，木龙三伏閒在隅。","检源之乐人间无，阿翁哺雏妻饷夫。","生来不作章句儒，但拟百斛量明珠。","东家击鲜大作社，西家酒熟携满觚。","诏书昨日五门下，天子尽赐今年租。"]},{"t":"耕乐吟二首 其二","f":"七言古诗","c":["近天不必城南社，范蠡湖头一茅宇。","瓜生陇上已离离，亘长南山少荒土。","出门岂识卿相尊，对客何忧子孙鲁。","岁祈五风十日雨，上无飞蝗下无虎。","四海从今尽中国，作歌且为歌洪武。","但存父子与君臣，风俗当如结绳古。"]},{"t":"海翁谣","f":"古风","c":["海翁随白鸥，白鸥亦不惊。","千金散如土，身与白鸥轻。","问翁甲子翁但笑，人间岂识女期生。","祖龙一别阜乡晚，已见六鳌脊腐三山倾。","天空潮落夜如水，月色下照珠宫明。","麻姑到家急汛扫桃核，酌酒为劝王方平。"]},{"t":"壬子春二月既望乘君子材拈余重游殳山遂燕陆景远氏来青堂与者丁一鹤董祖南景远父子及余季子翱一觞一咏不啻兰亭之会也酒半移尊公主墓侧而董海翁亦至子材遂大醉卧石上不能起命两童掖之登舟余与众客至东山兴尽而返目赋一首以纪其事云","f":"七言古诗","c":["老夫一月不见山，山癖无医殊未瘳。","野桃作花已烂熳，故人约我山中游。","日车出海风雨收，千岩万壑清如秋。","帝子何年上天去，黄鸟历历鸣相求。","来青堂上坐终日，饮酒况得公茔流。","金刀割鲜气颇壮，向日下地仍相留。","酒酣长歌动左右，诗成落笔蟠银钩。","平生快意在一适，放浪岂知公与侯。","玉台王母自千劫，海屋老人今几筹。","青春无价须秉烛，明朝花落令人愁。"]},{"t":"题徐复初参政骢马图","f":"七言古诗","c":["青骢万里来安西，五花满身玉削蹄。","将军大雪骑出塞，风鬃未洗龙城泥。","何人落笔通造化，天上房星降中夜。","朱衣老奚惊有神，不独开元数曹霸。","漠南漠北千帐空，将军赐爵论边功。","此马岂与凡马同，解鞍落日从远放，黄金台高春草丰。"]},{"t":"吴山人诗","f":"古风","c":["吴山人，读书不作章句儒，西上玉笥观匡庐。","寻龙经在神莫閟，金盌玉杯何处无。","负士哀哀者鄮氏，兄死无儿惟有弟。","山人为卜范萧峰，水抱山回上田美。","紫荆一荣复一枯，冈头日落啼老乌。","百金报吴笑不顾，一诗价重双明珠。","君不见孙生瓜熟能供客，客指黄花洞前域。","山空白鹤今有村，白鹤南飞杳无硛。"]},{"t":"胡虔雪猎图为徐复初赋","f":"古风","c":["太古天骑宅幽朔，平沙四面苶城郭。","生儿岂识种禾黍，走狗呼鹰共为乐。","北风颾颾大雪湿，越堑凌冈马蹄急。","弓开满月不虚发，赤豹玄熊号且立。","日暮两狼归挂鞍，燕支劝酒左右弹。","一时快意良不恶，金刀割鲜行玉盘。","君不见汉家天子猎四海，塞下将军归奏凯。","青丘云梦何足誇，猛虎长鲸肉俱醢。"]},{"t":"十月三日过梧桐泾时官籍仆彦宅彦庞氏唐氏自经感而赋之","f":"七言律诗","c":["天寒水清石齿齿，杏叶初黄豆花紫。","舞榭歌台不见人，头白乌啼月明里。","当时豪侠倾五侯，一荣一枯八十秋。","绿珠亦解死金谷，草露作泪无时流。"]},{"t":"送车定夫赴莱芜簿","f":"七言古诗","c":["空青丹砂世所奇，乌喙昌阳亦皆用。","赤城车子玉峰孙，年过四十犹未贡。","南宫昨日献文词，百族纷纷见孤凤。","一官初试莱芜邑，古人今人差伯仲。","釜中有鱼晨不爨，案上无萤夜犹诵。","尚思论道程朱后，玉峰先生最该综。","一编大学正全书，子后传之四方共。","平生河神齑百瓮，岂望为郎食官俸。","迢迢北上不可迟，十月黄河雪先冻。","老夫买酒无一钱，作诗直比琅玕送。"]},{"t":"徐给事山水歌","f":"古风","c":["吴门故人徐给事，一水一山称绝艺。","浓豪燥墨随意成，位置非难在神气。","大山积铁青巑岏，小山起伏蛟龙蟠，水有百道喷薄之飞湍。","宛然坐我明星玉女下，五月六月松声寒。","荆关笔法自奇古，未数画师扬契丹。","仙家楼台十二阑，饭煮胡麻须可餐。","采药何人入少室，读书有客居王官。","我游白下未得去，五更出门雪满鞍。","虚空翠黛不复览，一日剪向高堂看。","员外张公尚文采，身住南宫志沧海。","李白已死今无诗，卷示老夫增慷慨。","近来好事复持去，梦觉烟霞竟安在。","白鹤夜怨清猿悲，山中春老归何时。","写我平生有声画，价君太古无声诗。"]},{"t":"精卫愤","f":"古风","c":["乍登太行，莫涉沧海水。","天吴九首马一角，白浪崩山飓风起。","精卫万古长衔冤，无人为汝笺天门。","孝子亦何辜，死挂扶幸垠。","愿衔西山石，朝飞暮飞折两翼。","西山石尽海不极，月黑珠宫閟魂魄。","魂魄不归思可已，乍登太行，莫涉沧海水。"]},{"t":"凤皇台怀古","f":"七言古诗","c":["凤皇台前山色古，凤皇已去今平土。","雕梦绣柱非昔时，月白连营宿貔虎。","登高四顾何壮哉，金陵形胜自天开。","酒星不见李太白，何人与倾三百杯。","拒霜卷红秋草绿，尚想英雄起相逐。","山河万古一金瓯，宫殿中天开玉烛。","元嘉之事安足谈，琅琊法尧终可惭。","葱葱佳气今复见，黄旗紫盖天东南。","当垆小姬字桃叶，笑我重来发如雪。","相逢莫惜千金裘，五夜喙箫醉明月。"]},{"t":"云中烈妇行","f":"古风","c":["出门何匆匆，姑行妇及从。","萧条百里外，但见旌旗红。","东家破柱索珠玉，西家夫死无人哭。","凤皇中道忽相失，豺虎满城谁敢触。","仰天天高，局地无泉。","白刃如雪，马屯塞川。","乍可玉碎，宁能瓦全。","旁人还共悲，妾死犹生年。","云中之英，雪峰万仞同崭然。"]},{"t":"题倪云林木石","f":"七言古诗","c":["东海倪迂十年别，昨日朱颜今白发。","作诗作画犹未休，酒后挥毫见三绝。","缘江白屋知几家，参天古木僵龙蛇。","苍皮半死或垂瘿，赤叶未脱都成花。","我知用心亦独苦，众史庸奴焉足数。","英华已剥馀本根，老气尚存冰雪古。"]},{"t":"毛女辞二解 其一","f":"古风","c":["一叶为衣双足赤，何年入山不火食，宫中歌舞犹能忆。","犹能忆，空徘徊，白日晚，阿房灰。"]},{"t":"毛女辞二解 其二","f":"古风","c":["凤皇钗脱鸟云亸，红叶花鲜还自把，朝朝暮暮南山下。","南山下，千万年，不采药，能神仙。"]},{"t":"题山水四景 其一","f":"七言绝句","c":["雨前雨后花满川，春光浩荡殊可怜。","山人日高眠不起，劝酒提壶落红里。"]},{"t":"题山水四景 其二","f":"七言绝句","c":["青林五月不知暑，玉女晒衣中夜雨。","客至清谈酒更添，白杨梅熟荐吴盐。"]},{"t":"题山水四景 其三","f":"七言绝句","c":["田家酒熟当早归，天气渐凉催授衣。","一夜西风破霜蕊，芳菲不共芙蓉死。"]},{"t":"题山水四景 其四","f":"七言绝句","c":["天云漠漠四野低，大山小山玉戻齐。","春还何处寻消息，花发枝南与枝北。"]},{"t":"洪武八年三月奉旨分教中都生自龙江至临淮凡十日为赋长谣以纪山川风景云","f":"古风","c":["三月金陵别，匆匆催夜发。","无处不伤春，杨花半江雪。","海水忽成潮，奔流亦西回。","行人度江去，何日金陵来。","可爱焦山孤，直对妙高台。","天遣神鳌戴拳石，青莲一朵龙宫开。","雨足南风生五两，楚柁吴樯竞来往。","海门雁阵入云飞，甓社鲎帆迎月上。","信宿过淮阴，不见淮阴祠。","将军竟为儿女诈，空忆钓鱼城下时。","行行泗州近，岸有铁佛古。","水妃泉下伏，犹疑作雷雨。","平生不出户，焉知天下奇。","前瞻凤阳城，宫殿起参差。","两都未足论，天启万年基。","四方此会同，车马填九逵。","苦酒能宽忧，酌酒日赋诗。","远游颇快意，白发羞成丝。","怅望芳草绿，秪合归樵牧。","明年上疏当乞身，葛洪井西镜湖曲。"]},{"t":"桃核杯歌","f":"楚辞体","c":["度朔之山有桃屈蟠千里兮，结子轮囷大如瓮。","天上惟闻方朔偷，人间不许刘郎种。","何年阿母燕云台，食桃戏作鸳鸯杯。","道士王回献阙下，缺月夜堕青天来。","玉杯未辩新垣诈，学士银杯一时化。","安知别有蓬莱物，百斛葡萄向君泻。","鸾歌凤舞在君前，酌此可以求神仙。","山中看花试挟双窈窕，一醒一醉三千年。"]},{"t":"题华山图","f":"古风","c":["太华五千仞，石色青如苔。","崭然表西极，肇自鸿濛开。","河流破石雷霆激，父老空谈巨灵迹。","山寒五月疑清秋，鸟飞不过仙掌侧。","我欲上从羽客云台间，铁锁高县犹可攀。","千叶池莲食之久不死，明星玉女相往还。","相往还，人间万劫才一息。","峰头大笑惊下方，日落咸阳秋草碧。"]},{"t":"赠乘槎客","f":"七言古诗","c":["六月淮南不知暑，闭门日日风和雨。","乘槎仙客何处来，把酒张灯连夜语。","酒酣示我榰机石，曾到天河见河鼓。","人间倏忽三千秋，弱水三枯海鳌腐。","吴争越战空陈迹，山绕钱塘作龙虎。","柳外楼台十万户，太平重自南朝数。","吴娘玉面胜梨芯，解向尊前胡旋舞。","乐极哀来泪相续，城郭秋深半禾黍。","内前树老啼寒鸦，山月无情照今古。","白首相看亦偶然，忘形何必论宾主。","天为酒星地酒仙，麒麟将相皆黄土。","约我他年一棹归，西湖烟浪从渔父。"]},{"t":"李将军歌","f":"七言古诗","c":["汉家李广旧无双，年少提兵飞度江。","黄石素书心已授，龙文赤鼎手能扛。","不作诸生自辛苦，千金结客轻如土。","朝呼野外黄头鹘，夜杀山中云毛虎。","天子诏书开四夷，五年出塞事征西。","三冬冰雪皴人肉，万里关山辟马蹄。","今日相看凤阳道，绣袍换酒情编好。","虎符金印来未迟，铁砚毛锥吾已老。","豪侠平生感慨多，尊前击剑起高歌。","定知班固文章在，为勒燕然示不磨。"]},{"t":"题赵子昂松石修篁图","f":"七言古诗","c":["白发王孙老蓟门，逢人只说山中趣。","酒酣落笔有天机，写作阴厓百年树。","一株偃蹇龙蛇影，绕屋风声三伏冷。","流脂入地成虎魄，死骨经雷缩人瘿。","森森竹石俱苍然，一日坐我天姥前。","王孙跨鹤归何年，山空月明啼杜鹃。"]},{"t":"太行山谣送靳手中归潞州","f":"楚辞体","c":["太行之山包燕跨晋兮，拔地千仞谁能踰。","天何不铲羊肠九折坂，使人万古方驾而长驱。","山寒六月积冰雪，穷猿怪鸟左右时相呼。","故人玉女泉头居，北上岂不愁崎岖。","翔风吹沙不见涂，青天茫茫飞鸟孤。","我歌短歌倾酒壶，勿言太行险，人间之险何时无。"]},{"t":"次韵荅王蕴德纪善雨中见寄","f":"七言古诗","c":["老夫三月不出门，懒性有如嵇叔夜。","圣明遇物先采擢，枯槁于时亦沾洒。","病驹只合中野弃，寒雀宁思上林下。","印常不启信官间，书亦慵耽从容假。","淮南六月如早秋，未脱吴绫颇相讶。","白雨三更沧海立，黄河一道青天泻。","池翻红艳落莲衣，石长绿文成藻藉。","姑恶时鸣父老忧，鬼车夜过儿童怕。","空怀南苍人相远，岂有东家马堪借。","百钱沽酒愧瓶空，斗米如珠抱衾卖。","已惭不作子虚赋，尚托端居广文舍。","隐几南窗亦自高，驱车九陌知谁暇。","识字终非杨子博，题诗误许曹刘亚。","但觅丹砂苦未成，久知白发那能化。","两峰绝境可诛茅，何处良田足甘蔗。","赤城仙子玉符孙，双璧今倾凤台价。","楚筵设醴未应忘，齐门鼓瑟空遭骂。","时看新学气如虹，病送残年肉销胯。","投劾终当去石门，日斜田父茅檐话。"]},{"t":"日苦短辞九章","f":"古风","c":["日苦短，夜何长，蟋蟀悲鸣在北堂。","白露下，河汉明，黄姑织女东西望。","抚云和，荐清觞，同心胡为各一方。","麟有趾，凤有章，苍姬感之国乃昌。","世之微，佞为良，铅利一割投干将。","悦巧辞，隳大防，蟾蜍食桂廱毙桑。","圣去鲁，轲游梁，道既枘凿徒伥伥。","昔少壮，今老苍，朝荣暮歇同舜英。","胡不归，阻异乡，孰假以翼今高翔。"]},{"t":"题海山秋晓便面","f":"古风","c":["巫子门前吹飓风，一杯瀛海白浮空。","周回已吞赤县小，浩荡直与天河通。","方壶员峤不可见，弱水更在三韩东。","无人鞭石为梁跨万里，下拾明月龙王宫。","金鸡三叫呼客梦，日车夜衮波涛红。","楼居之人起相顾，白玉窗户光曈曈。","我愿羲和停六龙，岂不能长悬照下土，朝东暮西使人成老翁。","至今累累野葬悲英雄，六龙为我驻光彩，千古万古游无穷。"]},{"t":"孤松图","f":"七言律诗","c":["峨眉古松寒不死，曾见仙人三洗髓。","霜摧雨剥雷震馀，千尺老蛟鳞甲紫。","城南桃卷千万株，乱后一株今亦无。","长身独立何偃蹇，正直自是神明扶。"]},{"t":"送袭封衍圣公孔希学还阙里","f":"七言律诗","c":["星斗光芒万丈腾，赐书连舸出金陵。","雁违青冢天将雪，马度黄河夜已冰。","博士经存终汉出，上公爵重自唐升。","喜闻手植庭中桧，翠接东蒙几百层。"]},{"t":"送愚上人归越中并木奎方舟长老","f":"七言律诗","c":["天界归来亦已迟，庭松此日定回枝。","山中结社无灵运，海上留衣有退之。","鹤去云霄随锡杖，龙收风雨入军持。","西湖若见方舟老，为说三生梦里诗。"]},{"t":"观海与鲍仲孚同赋","f":"七言律诗","c":["弱水之外有蓬莱，云中髣髴金银台。","终驱汎滥群流合，始与鸿濛一气开。","石壁三更看日上，星槎八月到天回。","麻姑何处窥清浅，近日无书寄鹤来。"]},{"t":"送户部尚书贡泰甫开司闽中榷盐易米给京师 其一","f":"七言律诗","c":["昨日除书下五门，地兼中外亦殊恩。","三山迥出南荒小，八座元同北斗尊。","悟主已知如内相，封侯终见自公孙。","荆扬乐土今凋擦，他日从客为一言。"]},{"t":"送户部尚书贡泰甫开司闽中榷盐易米给京师 其二","f":"七言律诗","c":["两隅未挣出师频，圣主经营伏老臣。","天河转粟遥通蓟，腊月看花近到闽。","道上豺狼应避马，山中猿马不惊人。","公馀定有诗千首，好托边鸿寄蚤春。"]},{"t":"题徐太章白鹤山居","f":"七言律诗","c":["孤烟一曲紫云村，好客寻常远到门。","水落已知鱼可笱，夜深不畏虎夔藩。","邻人送酒酌花下，稚子读书当树根。","白鹤千年时过上，屯中还有令威孙。"]},{"t":"三月晦日","f":"七言律诗","c":["王师未下姑苏台，客子野次独徘徊。","城南酒徒不复见，院里桃花空乱开。","儿女新年俱已长，弟兄何日却同回。","故人重里寄书至，相约山中拂紫苔。"]},{"t":"寄内弟陆熙之","f":"七言律诗","c":["我别禦儿溪上宅，月当二十四回新。","如何故国尚戎马，即恐比邻非昔人。","箫鼓谁家犹作社，楼台废苑不成春。","夜寒忆尔无由见，怅望黄姑祈木津。"]},{"t":"寄潘时雍","f":"七言律诗","c":["潘岳闲居学灌园，一椽茅屋近青门。","野乌得食频将子，慈竹团阴定长孙。","宾客过门车盖合，儿童汲井辘轳喧。","春风金谷空流水，且共高歌醉瓦盆。"]},{"t":"送翁镇方归天台","f":"七言律诗","c":["云气空蒙是赤城，高歌归去不胜情。","天倾沧海东南迥，地接丹丘日夜明。","念我好将黄独寄，知君先向石桥行。","春风一路啼莺巧，定有花间窈窕迎。"]},{"t":"题云溪耕隐","f":"七言律诗","c":["屋外青山青似莲，云溪隐者即神仙。","桑麻杜曲非无地，鸡犬桃源别有天。","载酒邻翁时叩户，卖鱼溪女不论钱。","卧龙何事烦三顾，祗合隆中老岁年。"]},{"t":"题丁成之清樾轩","f":"七言律诗","c":["九龙山前处士宅，草堂低小尽青苔。","树阴满地日不到，水气著人秋已回。","无数黄鹂相对语，有时翠碧忽飞来。","移床与客竹间坐，千里好风何快哉。"]},{"t":"郑宪卿省郎织毯松江还诗以送之","f":"七言律诗","c":["鹤城翠织出天机，卷付星查使者归。","瑞草奇花春欲动，彩鸾青鹤昼交飞。","峒人不用誇山罽，朝士何须惜地衣。","闻说千秋佳节近，吴宫高会更光辉。"]},{"t":"云间见李克敏将归吴陵作诗为别","f":"七言律诗","c":["与子西东二十霜，尚思年少醉钱唐。","人间日月如行客，马首山川忽异方。","历历早莺初变语，翩翩归雁未成行。","明朝陌上重分袂，更尽吴姬酒一觞。"]},{"t":"赋小瀛洲 其一","f":"七言律诗","c":["海上瀛洲碧水新，地连方丈绝风尘。","九光霞馆邀王母，一曲鸾笙降玉晨。","若木回枝长挂日，桃花结子不知春。","祖龙谩自求方士，却恐流传语未真。"]},{"t":"赋小瀛洲 其二","f":"七言律诗","c":["仙人长伯白银宫，不似淮王礼八公。","日月自周三岛外，山川尽缩一壶中。","亦麟紫凤池台胜，姹女河车服食同。","清夜步虚相和处，琪花如雪又春风。"]},{"t":"题苧溪渔友宅","f":"七言律诗","c":["徵君白苧溪头住，细雨斜风一短蓑。","山木两边啼杜宇，浪花千顷落鴐鹅。","故人且复辞光武，使者何须认志和。","我亦买田来结屋，沙棠船小日相过。"]},{"t":"灵鹫观灯","f":"七言律诗","c":["天乐风传应壑雷，鹫峰春色似蓬莱。","一天象纬迎秋转，千月龙宫彻夜开。","西国胡僧依树坐，上方玉女散花来。","夜深借榻山房宿，更欲题诗到上台。"]},{"t":"谢贾齐臣惠碧盌","f":"七言律诗","c":["万里坚昆来碧盌，青莲十叶类天成。","于阗苍玉本同色，韶州白瓷空得名。","马湩可能羞北馔，驼蹄且复荐南烹。","茅斋此日足家具，一诗为报故人情。"]},{"t":"题静天镜碧水春轩","f":"七言律诗","c":["绿波如酒不成潮，一曲潜通海眼遥。","祗树国深青鸟下，桃花浪煖白鱼跳。","疏星夜列开天镜，细雨朝飞落虹桥。","杜老赋诗须重过，远公结社肯相邀。"]},{"t":"送兴福寺镇静庵","f":"七言律诗","c":["西山楼阁涌波涛，西国高僧见白毫。","贝叶有文留藏室，天花无迹上方袍。","毒龙在钵秋云湿，驯虎当门夜月高。","听法他年陪相国，定因元亮置松醪。"]},{"t":"六月三日泛舟","f":"七言律诗","c":["六月三日好天气，清江转柁雨晴初。","树头云敛出红日，石脚水生跳白鱼。","何处老翁还独钓，可怜游子未安居。","野王堆前三女窦，得意唱歌随所如。"]},{"t":"七夕","f":"七言律诗","c":["沧江雨歇暑渐微，银床一叶迎秋飞。","牵牛相对织女出，明月不照征夫归。","寸心耿耿只自苦，双鬓萧萧今更稀。","仰候神光向中夜，秋萤暗度鸳鸯机。"]},{"t":"十一月廿三日夜集次韵卢廷举","f":"七言律诗","c":["河桥春向柳条归，买酒从教更典衣。","倒海北风三日盛，著人南雪六花飞。","铜盘烧蜡诗初就，羯鼓催觞令不违。","身后空名亦何用，独怜张翰早知几。"]},{"t":"剪韭轩","f":"七言律诗","c":["三韭行厨亦浪誇，傍人犹笑庾郎奢。","春宵翠截山中叶，腊月黄分雪后芽。","野饭犹能留上客，侯鲭岂复到贫家。","盘中一箸青丝细，绝胜芜菁散作花。"]},{"t":"题玉士亨看山处","f":"七言律诗","c":["看山何处候神仙，地近城南尺五天。","林屋雪消攒玉笋，上方云影出青莲。","行人独去西风里，倦鸟双回落照边。","此日骑曹谁记马，閒支手板思悠然。"]},{"t":"元夕次韵铁崖杨先生","f":"七言律诗","c":["元戎出号初鸣铎，狂客忘归更赋诗。","貔虎千屯防要地，鱼龙百戏梦清时。","月临粉蝶南楼静，天接沧江北斗垂。","可得夜游重秉烛，佳人双唱玉交枝。"]},{"t":"二月十六日雨中遣兴","f":"七言律诗","c":["城头落日啼乳鸦，城中烟火冷千家。","断云漠漠夜还合，急雨纷纷风更斜。","世乱不归空洒泪，春深何处独看花。","白龙堆前水二尺，明日泛舟携紫霞。"]},{"t":"送凌彦冲归杭","f":"七言律诗","c":["正好听君苏武慢，倾壶共坐白鸥沙。","十年戎马犹塞路，三月归舟催到家。","江燕与人同是客，野桃成子乱飞花。","使回多寄平安字，要看张颠醉墨斜。"]},{"t":"寄林叔大","f":"七言律诗","c":["湖州别驾三年别，文采风流想见之。","水晶宫里无传箭，浮玉山前多赋诗。","海燕空归寻旧宅，具蚕未老卖新丝。","金闺学士临池处，还与何人话昔时。"]},{"t":"槐阴亭","f":"七言律诗","c":["云团车盖起重重，文正三朝相业隆。","种树百年蟠厚地，读书六月坐清风。","蝉吟露叶初回梦，虫吐秋丝忽堕空。","今日洛阳卿相宅，牡丹谁看状元红。"]},{"t":"立夏日","f":"七言律诗","c":["江寒雨急仍北风，扣户喜闻南巷翁。","锦城鲊送蒲茅白，玉盌酒泻桃花红。","三月忽惊春似客，百年那得老还童。","一双黄鹂寂无语，飞过小月高楼东。"]},{"t":"题云深处","f":"七言律诗","c":["朝看云出暮云归，翁住云深已息机。","海上仙人教种药，山中玉女未收衣。","须知倏忽神龙变，已作絪缊野马飞。","我亦无心共来往，五城宫阙梦魂稀。"]},{"t":"题夏士文园亭","f":"七言律诗","c":["窗户青红竹里开，竹深无地著尘埃。","山移阆花千峰出，水接银河一道回。","酿酒每留宾客醉，赋诗重许老夫来。","暖风迟日春如海，随意何妨坐绿苔。"]},{"t":"重午","f":"七言律诗","c":["北里共持菖歜酒，南翁未解木绵裘。","臼波青嶂三吴地，怪雨肓风五月秋。","挥泪几时朝凤阙，招魂何处觅龙舟。","海榴一点红如火，时序催人共白头。"]},{"t":"瑞莲 其一","f":"七言律诗","c":["双花相向复相辉，白帝西游拥一妃。","羽盖风清朝并载，珠宫月冷夜同归。","翠房已作鸳鸯结，红粉那成蛱蝶飞。","亭上酒醒杏不断，满汀暮雨湿仙衣。"]},{"t":"瑞莲 其二","f":"七言律诗","c":["秋水嘉莲瑞一门，初花惊见出同根。","美珠汉女无留迹，鼓瑟相灵有返魂。","相府昔年曾制曲，仙家今日重开樽。","合欢何限风流意，怨绿愁红谩自繁。"]},{"t":"题渊明像","f":"七言律诗","c":["素琴无弦不复鼓，清尊有酒还相持。","者奴迁鼎亦苦早，先生拂衣应已迟。","子房结客报秦日，武侯出师匡汉时。","古人今人本同调，坐对南山惟赋诗。"]},{"t":"题松鶮山居图","f":"七言律诗","c":["仙客卢敖东海头，好山百转接丹邱。","开田种玉一千顷，闭户读书三十秋。","云气上天如白鹤，茯苓入地化青牛。","年来浪迹吴淞道，梦里猿声忆旧游。"]},{"t":"寄奎方舟后用章二上人","f":"七言律诗","c":["奎公不种远公莲，卓锡西湖已十年。","路入雪山灵草合，泉通沧海毒龙眠。","听法每期双树下，题诗须到四卷前。","干戈满地伤飘泊，目断千峰紫翠烟。"]},{"t":"白莲","f":"七言律诗","c":["太液初花宿露团，香浓粉淡不胜寒。","金茎侧泻仙人掌，玉叶危擎帝子冠。","水阔天空愁欲堕，风清月落好谁看。","西湖肠断西施采，一曲菱歌唱未阑。"]},{"t":"中秋","f":"七言律诗","c":["中秋甲子无风雨，吹笛星桥意最关。","七宝已修天上月，三神不隔海中山。","故人此夜知何处，狂客经年且未还。","小队羽衣新按曲，广寒宫阙梦魂閒。"]},{"t":"钱塘秋夕","f":"七言律诗","c":["残蜡无光小院幽，梧桐一树更萧飕。","西陵风雨来清夜，南国山河入素秋。","鸡唱四邻呼客梦，雁回千里带边愁。","可怜季子貂裘弊，迟暮何为赋远游。"]},{"t":"奉寄崔伯恭左丞","f":"七言律诗","c":["武林城下捷书回，郡县遥知次第开。","一柱危擎南极正，三江远阻北人来。","讴歌复见唐虞德，匡济深期管葛才。","东阁几时陪笑语，云间夜夜仰中台。"]},{"t":"无题 其一","f":"七言律诗","c":["楼台十二近蓝桥，帘幕重遮半面娇。","洛浦有神通子建，天坛无意会文箫。","仙衣雪皎裁蝉翼，宝髻云松插凤翘。","月落红寒春梦断，相思空寄海门潮。"]},{"t":"无题 其二","f":"七言律诗","c":["锦瑟鸾笙恨总牵，尚思华屋对婵娟。","春风豆蔻初含日，玉女兰香未嫁年。","绡拆鸳鸯裁宝扇，酒行琥珀泻银船。","蓬莱一别三清浅，憔悴应知不及前。"]},{"t":"夜坐","f":"七言律诗","c":["夜寒蟋蟀语秋根，独客无眠忆故园。","天作穹庐笼四野，月飞明镜照千门。","胡笳相应时时发，戎马初生处处屯。","秉烛封书寄兄弟，一身犹滞海西村。"]},{"t":"立春日燕西清高士沧洲一曲歌者李氏善胡琴者阮仲朋引觞奏伎宾主尽欢即席赋诗","f":"七言律诗","c":["百花堂深香雾生，将军燕客更多情。","春光已到筼筜谷，客梦如在芙蓉城。","蛾眉八字远山碧，凤尾双丝流水清。","金樽美酒敌秋露，今日为君怀抱倾。"]},{"t":"别吕德常","f":"七言律诗","c":["黄鹤仙人道德尊，少年曾记及龙门。","王山照座联兄弟，白发升堂识子孙。","衰謉已知英气尽，激昂犹喜赏音存。","不堪杜宇催归客，明日扁舟出海村。"]},{"t":"姑苏","f":"七言律诗","c":["城溃姑苏伯业终，萧萧茂苑自秋风。","青丝白马来江表，紫盖黄旗入洛中。","宫殿独留残月照，绮罗应逐晓云空。","如何十万貔貅士，不及吴陵一旅雄。"]},{"t":"陆景周宅槁梧复荣以瑞梧命之为赋首","f":"七言律诗","c":["石上孤上百尺标，凤皇枝老尚萧萧。","半身秋委龙蛇蜕，一气春回霹雳焦。","影薄未能遮月色，声和犹待按云韶。","山童日夜勤封植，莫使青青露叶凋。"]},{"t":"钱唐春日","f":"七言律诗","c":["三月皇州望欲迷，涌金门外草初齐。","满山云气不见日，一雨天街都作泥。","温室树移鹦鹉去，玉津花落杜鹃啼。","断桥何日重携酒，醉和儿童唱大堤。"]},{"t":"遣兴","f":"七言律诗","c":["我住云间今四秋，恰如杜甫在秦州。","赋诗黄耳冢前去，打鼓白龙潭上游。","暮景飞腾如过翼，此身浩荡一虚舟。","黄尘九陌绕车盖，且伴老翁随海鸥。"]},{"t":"春和铁崖先生水仙入韵","f":"七言古诗","c":["千叶名花阆苑移，浓香百和为重肌。","藻翘半脱春如醉，翠袖轻扶夜更痴。","赋就陈王空自怨，佩遗交甫至今疑。","承恩不向金涂立，入道初将羽帐离。","步月有时羞素女，行云无意妒瑶姬。","水边寂莫谁能赏，林下风流总未知。","肠断二生孤旧约，眼明万槁出新枝。","朱弦五十闲瑶瑟，黄九为君重赋诗。"]},{"t":"二月五日燕夏士文漪澜堂与者鲁道原马文壁冯困如赋诗一首歌者张宝童不至故及之","f":"七言律诗","c":["漪澜堂上又东风，报荅春光酒未空。","海鸟一双鹏尾白，山花千朵鹤头红。","水边列坐皆词客，天上清歌少玉童。","不省日斜谁倒载，从教拍手笑山公。"]},{"t":"浙江亭观潮","f":"七言律诗","c":["山摧岸坼昼冥冥，动地西风带蜃腥。","沧海倒流吞日月，青天中裂走雷霆。","欲抬白马今无迹，莫信神鱼尚有灵。","一气虚空自升降，乾坤与我亦浮萍。"]},{"t":"嘉禾道中","f":"七言律诗","c":["秀州城下雪漫漫，一客东归更觉难。","雁度空江寒月黑，马嘶畏路晓风酸。","吴趋欲赋知谁和，漠节忘回不复看。","俯仰乾坤正萧瑟，云间身寄一枝安。"]},{"t":"五月十一日过璜溪访马文璧时同门吕德厚具酒相邀犹雨夜归明日文璧有诗见寄用韵荅之","f":"七言律诗","c":["因君怀抱未能开，白鹤矶头一棹来。","江黑坐看飞雨至，酒酣催趁落潮回。","故人有约金重过，野老无机不用猜。","明日山瓶犹未竭，当筵更掷左慈杯。"]},{"t":"支子","f":"七言律诗","c":["南风院落扫繁英，薝卜无人也自荣。","五月六花开白雪，何年三粒种青城。","已将色染天衣重，那惜香分水殿清。","胡蝶梦回闻更好，酒醒夜半月微明。"]},{"t":"绿阴轩夏日书怀","f":"七言律诗","c":["锦水西头处士家，深林无径绿阴遮。","窗前翠合书带草，阶下红开旌节花。","本藉居亭苏老病，屡从宴赏悦清华。","一双海鸟无机事，日日飞来傍钓槎。"]},{"t":"客居","f":"七言律诗","c":["移家处士桥西畔，六月蒲莲暗野塘。","乳鸭成花能黑白，风蝉隔叶自宫商。","买田不待沾微禄，垂钓须教具小航。","自比成都浣花叟，旁人应是笑清狂。"]},{"t":"风泾定光寺周回三里皆荷花彷佛有钱塘西湖之胜与筠谷高士同赋","f":"七言律诗","c":["南风隔浦闻花气，菡萏红开十里花。","宫女三更环白帝，洞庭千顷落明霞。","凿池不待烦灵运，载酒浑疑过若耶。","何日与君追胜赏，满船明日唱吴娃。"]},{"t":"题周伯昂水村图","f":"七言古诗","c":["爱尔读书阳羡里，乔林古木五湖东。","山如城郭铜棺并，水落田畴罨昼通。","野老犹能说周处，仙人何许觅张公。","园收橡栗霜初重，饭煮桃花岁屡丰。","马队岂堪延祖企，草堂今复见卢鸿。","已知贡赋随时给，还笑衣冠与俗同。","一艇微茫在烟浪，采菱歌断夕阳中。"]},{"t":"题刘商观奕图 其一","f":"七言律诗","c":["日落青山未了棋，两翁浑似海僧痴。","不辞虎口方争险，曾取龙牙会出奇。","春在洞天应不老，路经石室到今疑。","老樵若悟归来早，物外神仙岂复知。"]},{"t":"题刘商观奕图 其二","f":"七言律诗","c":["烂柯山头生白云，烂柯人去世空闻。","楸枰有路纵横列，石子如星黑白分。","寂寂中流方对垒，迢迢出塞未成军。","当时一著安刘氏，四老应宜策上勋。"]},{"t":"初冬口号","f":"七言律诗","c":["朝来吉语解离忧，四海销兵战伐休。","地辟尧封皆内属，江通禹凿已安流。","复见老生谈俎豆，遂闻壮士脱兜鍪。","种瓜好觅青门地，我亦为园学故侯。"]},{"t":"荅宇文仲美","f":"七言律诗","c":["五两夜逐秋鸿徂，十年辟兵无定居。","君今不奏子虚赋，我亦终返班生庐。","蹲鸱如斗足野饭，江鱼斫玉分王馀。","更种南山豆一顷，试看身子带经锄。"]},{"t":"冬日漫兴","f":"七言律诗","c":["大阴十日犹未解，腊月荆扬气候偏。","雨合树声来夜半，风催花信立春前。","酒徒已老今何处，狂客不归殊可怜。","山茶一株欲烂熳，百壶留我醉新年。"]},{"t":"巳酉立春日","f":"七言律诗","c":["今朝独酌黄柑酒，海曲逢春且自宽。","老爱陶潜家栗里，贫如杜甫客云安。","身轻不佩将军印，发短犹胜隐士冠。","试笔更题新帖子，风光无处不宜看。"]},{"t":"正月二日偕邵筼谷过吕德常宅留饮","f":"七言律诗","c":["东风十日消残雪，溪上水生三尺高。","同舟为觅故人去，闭阁不放老兵逃。","银甲弹筝促雁柱，玉盘缕肉鸣鸾刀。","夜深更尽百杯酒，莫惜淋漓宫锦袍。"]},{"t":"闻夏士文南归喜而有作特先寄之","f":"七言律诗","c":["传闻正月楼船发，灵鹊先人到竹扉。","突厥残兵河外徙，慕容诸客海边归。","山花雨过红于酒，江草春深绿染衣。","从此高歌太平日，往来林下定无违。"]},{"t":"寄陈性天 其一","f":"七言律诗","c":["西岳云台陈处士，移家秋浦四无邻。","光生虚室浑如雪，梦在清都别是春。","捣药或闻林下鸟，看花长误世间人。","我来更乞胡麻饭，为尔题诗满绿筠。"]},{"t":"寄陈性天 其二","f":"七言律诗","c":["汛扫天坛事老君，即从年少悟奇文。","青童汲井朝分乳，玉女裁衣夜染云。","水上赤鱼还可驾，山头白鹤自成群。","遥知客去能长啸，月冷天空半岭闻。"]},{"t":"三月五日饮于性天所有紫牡丹一本三花不意池馆丘墟之后复见于此为赋","f":"七言律诗","c":["名花新剖麝囊开，与客花时踏雨来。","越土一枝分阆苑，春风三朵出瑶台。","朝云重压珊瑚树，宿露低倾玛瑙杯。","重忆当时歌舞处，五侯池馆锦千堆。"]},{"t":"过沧洲有感","f":"七言律诗","c":["驷马桥南曲径赊，可堪重过故侯家。","青袍杜甫从漂梗，白发刘郎怨落花。","憔悴已看身似鹤，娉婷不见髻堆鸦。","野芳亭上春犹在，独坐吟诗到日斜。"]},{"t":"雨夜独坐","f":"七言律诗","c":["天阴十日不见星，蛰龙欲起驱雷霆。","大风五月忽动地，急雨三更如建瓴。","剪烛西窗还独坐，辟兵南国几时宁。","可怜骨肉求相隔，满树秋声谁与听。"]},{"t":"红菊","f":"七言古诗","c":["日照东笼烂若霞，误惊春色到山家。","宫人晓殢葡萄酒，道士秋开踯躅花。","莫擅鹅翎欺白雪，未论鹤顶养丹砂。","霜中苦节知谁并，雨里寒香只自誇。","寂莫也羞彭泽陋，风流还竞洛阳奢。","移樽九日来同赏，插帽休讥老孟嘉。"]},{"t":"雨夜","f":"七言律诗","c":["寒夜悲吟似夜蛩，银釭何事结花红。","愁听风雨三更尽，梦在波涛一叶中。","神女佩环归楚馆，鲛人机杼静珠宫。","连阴未解何由旦，翅湿南飞万里鸿。"]},{"t":"至日 其一","f":"七言律诗","c":["独客无家望转迷，山空木落气凄凄。","愁催短发浑如鹤，病觉长身不称犀。","书断蓟门天万里，禅经秦树雪千溪。","何由去学神仙术，一鼎丹砂夜自泥。"]},{"t":"至日 其二","f":"七言律诗","c":["日上扶桑晓色红，闭门慵似杜陵翁。","干戈送老甘人下，江海生春尚客中。","雪尽南枝开大庾，天回北斗挂空同。","试倾百斛芜城酒，未叹飘零两鬓蓬。"]},{"t":"送桑子材归縻塘","f":"七言律诗","c":["书囊未了复晨鸡，岁暮扁舟出大溪。","司马倦从枚乘客，伯鸾欣对孟光妻。","山通石屋风烟合，海接天河日月低。","一路梅花千树雪，春来约我酒重携。"]},{"t":"十二月十六日雨雪至十九日大雪次韵陈仲谋","f":"七言律诗","c":["膝六春前试出奇，三吴人贺太平时。","空山何处镵黄独，半夜无风雨白釐。","梁苑一时宾客盛，蓝关千里逐臣悲。","老夫坐看纵横落，醉拥鸢肩日赋诗。"]},{"t":"元夕","f":"七言律诗","c":["夜醉城南酒百缸，春来端使客愁降。","障开云母东西一，灯射琉璃日月双。","铁笛仙人传丽藻，金钗小妾度新腔。","归来误作三山梦，月色如冰白满江。"]},{"t":"郊居","f":"古风","c":["背郭茅堂低入燕，通村小径曲萦蛇。","碧鸡坊里诗人宅，石鳖崖前刺史家。","流水暗通三径竹，晓云浓掩一溪花。","他年著我林间老，垂钓共分鸂?沙。"]},{"t":"红梅","f":"七言律诗","c":["时世新妆学内家，渔人错认武陵霞。","百年艮岳空留树，一夜春风为染花。","月里嫦娥羞素服，山中仙客饵丹砂。","也知风骨依然在，雪后黄昏瘦影斜。"]},{"t":"蜀山图","f":"七言律诗","c":["连峰接岫写秦州，雨洗蛾眉积翠浮。","石出剑门皆北向，水通盐泽自西流。","松头一片秋云湿，鸟背千盘细路幽。","策马匆匆度关客，何如渔父一扁舟。"]},{"t":"庚戌中秋九思主人置酒予洎景渊副使子仁理问同会时风雨骤作抵暮旋止天无馀滓华月东出相与联句千馀韵皆大醉就寝遂忘所咏因复成一律","f":"七言律诗","c":["溪云通月转金盘，石上移樽兴未阑。","可惜少年今总老，莫辞良夜试同看。","玉人不得携王赵，词客犹能敌孟韩。","细数中秋知又几，松花新酒更须乾。"]},{"t":"归殳山一首寄杨德中丁一鹤","f":"七言律诗","c":["殳山即与浣花同，犬吠鸡鸣处处通。","卜宅定如唐杜甫，部符须得汉文翁。","荷歌夜雨衰犹绿，枣落秋风熟已红。","一鹤道人今可过，九龙山客试相从。"]},{"t":"水芙蓉","f":"七言律诗","c":["万里名花蜀上分，澄红浑似锦江濆。","夜承仙掌三清露，春剪巫山一片云。","未许王家誇少妇，还从卓氏妒文君。","所思欲寄知何处，雁断天南日色醺。"]},{"t":"寒夜忆梅拟西昆","f":"七言律诗","c":["星河西转夜初长，梦断罗浮月在梁。","青女五更欺病骨，玉人千里割愁肠。","铜龙水满声催漏，绛蜡花销泪作行。","明发南枝应有雪，试从树底觅春光。"]},{"t":"次韵陈仲谋","f":"七言律诗","c":["一夜秋霜入镜中，静观诸妄已圆融。","离禽自托寒枝小，病马犹思碧草丰。","出海云霞无旦暮，红天日月自西东。","危楼独倚无穷思，心事何人得与同。"]},{"t":"次韵杨鸣鹤","f":"七言律诗","c":["玄圃沧洲愿未酬，倏忽光景岂能留。","江草江花还刺眼，春风春雨又从头。","已知出处非同调，且拟登临为写忧。","尹看南山尽松柏，英雄何处葬眠牛。"]},{"t":"发春试笔","f":"七言律诗","c":["宫花无意插乌巾，暂到金门遂乞身。","不用天官书上第，已蒙学士唤山人。","葛洪井畔应堪老，范蠡湖边又见春。","重赋遂初惭造化，狂歌痛饮乐吾真。"]}]};